const boardAudit=(g,type,data={})=>{g.playerBoardAudit.events.push({type,encounter:g.encounter+1,round:g.round,...data})};
const boardLevel=n=>n>=5?3:n>=2?2:1;
function validateBoard(g){const violations=[];for(const h of g.party){if(h.hp<0||h.hp>h.maxHp)violations.push(`${h.role}: HP ${h.hp}/${h.maxHp}`);for(const [a,n] of Object.entries(h.mastery||{}))if(n<0||n>5)violations.push(`${h.role}.${a}: track ${n}`)}g.playerBoardAudit.consistencyChecks++;g.playerBoardAudit.violations.push(...violations);return violations}
function rogueHero(){return{role:'rogue',abilities:[],hp:9,maxHp:9,deck:[],draw:[],discard:[],hand:[],levels:{},invested:{},casting:null,actions:CONFIG.actionsPerRound,shield:0,counter:0,evasion:false}}
function mageHero(){return{role:'mage',abilities:[],hp:8,maxHp:8,deck:[],draw:[],discard:[],hand:[],levels:{},invested:{},casting:null,actions:CONFIG.actionsPerRound,shield:0,counter:0,evasion:false}}
