const HERO_KILL_XP=3,HERO_XP_THRESHOLDS=[9,11,13,15,17];
const HERO_BAG_SLOTS=6,APPLE_HEAL=2;
const PLAYER_BOARD_ENEMIES={goblin:{hp:16,damage:3,tactic:2},engineer:{hp:18,damage:2,special:5},warchief:{hp:20,damage:4,special:5},miniBoss:{hp:40,damage:6,tactic:3,special:5,summonThresholds:[25,10]},miniMob:{hp:4,damage:1}};
function enemyLabel(e){return e.type==='miniBoss'?'Grum’Arat, Strega del Miasma':e.type==='engineer'?`Artificiere Ranide ${e.id}`:e.type==='warchief'?`Rana Warchief ${e.id}`:e.type==='miniMob'?`Girino Putrescente ${e.id}`:`Razziatore Ranide ${e.id}`}
const ENEMY_ART={goblin:'assets/rana-razziatrice.jpeg',warchief:'assets/rana-warchief.jpeg',engineer:'assets/rana-ingegnere.jpeg',miniBoss:'assets/grumara-miniboss.jpeg',miniMob:'assets/girino-putrescente.jpeg'}
function weaponArt(h,slot){const m={warrior:['sword','shield'],healer:['staff-priest','wand-priest'],rogue:['dagger-left','dagger-right'],mage:['staff-mage','wand-mage']};return (m[h.role]||['sword','shield'])[slot]};
const noteBeforeTheme=note;
note=function(g,message){const themed=String(message).replace(/Mini Boss(?: \d+)?/g,'Grum’Arat, Strega del Miasma').replace(/Goblin Ingegnere (\d+)/g,(_,id)=>enemyLabel(g.enemies.find(e=>e.id===+id)||{id,type:'engineer'})).replace(/Goblin (\d+)/g,(_,id)=>enemyLabel(g.enemies.find(e=>e.id===+id)||{id,type:'goblin'})).replace(/(\d+) Goblin\b/g,(_,count)=>`${count} ${+count===1?'Razziatore Ranide':'Razziatori Ranidi'}`).replace(/\bServitori\b/g,'Girini Putrescenti').replace(/\bServitore\b/g,'Girino Putrescente');return noteBeforeTheme(g,themed)};
function diffDelta(g){return {easy:-10,medium:0,hardcore:20}[g&&g.difficulty||'medium']||0}
function applyPlayerBoardEnemyStats(g){const tokens=g.exploration?currentExplorationRoom(g.exploration)?.fighters||[]:[],fighters=g.enemies.filter(e=>e.type!=='miniBoss'&&e.type!=='miniMob'),types={ENGINEER:'engineer',WARCHIEF:'warchief'};fighters.forEach((e,index)=>{if(tokens[index])e.type=types[tokens[index]]||'goblin'});for(const e of g.enemies){const cfg=PLAYER_BOARD_ENEMIES[e.type];if(!cfg)continue;e.hp=e.maxHp=Math.max(1,cfg.hp+diffDelta(g));e.damage=cfg.damage;e.megaBombCasting=false;e.casting=null;e.summonThresholdsTriggered=[]}}
function xpThreshold(h){return HERO_XP_THRESHOLDS[h.heroLevel-1]||null}
function grantKillXp(g,enemy){if(!g.playerBoardEnabled)return;g.telemetry.progression.kills++;for(const h of aliveHeroes(g)){const threshold=xpThreshold(h);if(!threshold)continue;h.xp+=HERO_KILL_XP;g.telemetry.progression.xpGranted[h.role]+=HERO_KILL_XP;boardAudit(g,'XP_GAINED',{hero:h.role,enemyId:enemy.id,enemyType:enemy.type,value:HERO_KILL_XP,xp:h.xp,threshold});if(h.xp>=threshold){const from=h.heroLevel;h.heroLevel++;h.xp=0;h.pendingLevelRewards++;h.maxHp+=2;h.hp+=2;g.telemetry.progression.levelUps[h.role]++;boardAudit(g,'HERO_LEVEL_UP',{hero:h.role,from,to:h.heroLevel,maxHp:h.maxHp,nextThreshold:xpThreshold(h)});note(g,`⬆ ${NAMES[h.role]} raggiunge il livello ${h.heroLevel}: +2 HP e ricompensa talento/carta a fine combattimento.`)}}}
function nextAdvancementReward(h){const source=h.advancementQueue?.shift();return source?{hero:h,ability:h.abilities[Math.floor(Math.random()*h.abilities.length)],source}:null}
function advancementRewards(g){return aliveHeroes(g).map(h=>{h.advancementQueue=Array(h.pendingLevelRewards||0).fill('level');h.pendingLevelRewards=0;return nextAdvancementReward(h)}).filter(Boolean)}
function resetHeroTurn(g){g.turnOrder=(g.selectedRoles?.length?g.selectedRoles:g.party.map(h=>h.role));g.activeTurnIndex=0;while(g.activeTurnIndex<g.turnOrder.length&&!aliveHeroes(g).some(h=>h.role===g.turnOrder[g.activeTurnIndex]))g.activeTurnIndex++;g.activeRole=g.turnOrder[g.activeTurnIndex]||null}
function advanceHeroTurn(g){if(!g.playerBoardEnabled)return;if(g.state==='restoring')return advanceRecoveryTurn(g);if(g.state!=='playing')return;const current=g.party.find(h=>h.role===g.activeRole);if(current?.actions>0||current?.preparationPending||current?.evasionFreeFlip)return;do g.activeTurnIndex++;while(g.activeTurnIndex<g.turnOrder.length&&!aliveHeroes(g).some(h=>h.role===g.turnOrder[g.activeTurnIndex]));if(g.activeTurnIndex<g.turnOrder.length){g.activeRole=g.turnOrder[g.activeTurnIndex];note(g,`▶ Turno ${NAMES[g.activeRole]}.`);return}prepareManualOverlordTurn(g)}
function passHeroTurn(g){const h=g.party.find(hero=>hero.role===g.activeRole);if(!h||!['playing','restoring'].includes(g.state))return false;if(g.state==='playing')while(normalizePreparation(h)){const index=h.hand.findIndex(preparationDiscardable);if(index<0)break;discardPreparation(g,h,index)}h.preparationPending=0;h.actions=0;h.evasionFreeFlip=false;note(g,`→ ${NAMES[h.role]} passa${g.state==='restoring'?' il recupero':''}.`);advanceHeroTurn(g);return true}
function eatApple(g,h,slotIndex){const slot=h?.bag?.[slotIndex];if(!['playing','restoring'].includes(g.state)||h.role!==g.activeRole||h.actions<1||h.hp<=0||h.hp>=h.maxHp||slot?.item!=='apple'||slot.count<1)return false;const healed=Math.min(APPLE_HEAL,h.maxHp-h.hp);h.hp+=healed;h.actions--;slot.count--;if(!slot.count)h.bag[slotIndex]=null;g.telemetry.items.applesEaten[h.role]++;g.telemetry.items.appleHealing[h.role]+=healed;boardAudit(g,'APPLE_EATEN',{hero:h.role,slot:slotIndex,healed,remaining:slot.count||0});note(g,`🍎 ${NAMES[h.role]} mangia una mela: +${healed} HP (1 azione).`);return true}
function removeOneWound(h){const deckIndex=h.deck.indexOf('wound');if(deckIndex<0)return false;h.deck.splice(deckIndex,1);for(const zone of [h.hand,h.draw,h.discard]){const index=zone.indexOf('wound');if(index>=0){zone.splice(index,1);break}}return true}
function consumeBagItem(g,h,slotIndex){const id=h.bag[slotIndex]?.item;h.bag[slotIndex]=null;g.telemetry.items.itemsUsed[id]=(g.telemetry.items.itemsUsed[id]||0)+1;boardAudit(g,'BAG_ITEM_USED',{hero:h.role,item:id,slot:slotIndex})}
function discardBagItem(g,h,slotIndex){const slot=h?.bag?.[slotIndex],item=TREASURE_ITEMS[slot?.item];if(!slot||!item)return false;h.bag[slotIndex]=null;g.telemetry.items.discarded=(g.telemetry.items.discarded||0)+1;boardAudit(g,'BAG_ITEM_DISCARDED',{hero:h.role,item:slot.item,count:slot.count||1,slot:slotIndex});note(g,`🗑 ${NAMES[h.role]} elimina ${item.name} dalla Bag.`);return true}
function useBagItem(g,h,slotIndex,targetRole=null){const id=h?.bag?.[slotIndex]?.item,item=TREASURE_ITEMS[id],turnKey=`${g.encounter}:${g.round}:${g.state}`;if(!item||item.kind==='equipment'||!['playing','restoring'].includes(g.state)||h.role!==g.activeRole||h.hp<=0)return false;const needsAction=!['bronze_whetstone','bronze_crystal','silver_runestone','silver_sacred_crystal','silver_haste'].includes(id);if(needsAction&&h.actions<1)return false;if(id.includes('potion')&&!id.includes('evasion')&&id!=='silver_haste'&&h.hp>=h.maxHp)return false;if(id==='silver_haste'){if(h.actions>=CONFIG.actionsPerRound||h.hasteRound===turnKey)return false;h.actions++;h.hasteRound=turnKey}else if(id==='bronze_whetstone'||id==='silver_runestone'){if(h.itemWeaponBonus)return false;h.itemWeaponBonus=2}else if(id==='bronze_crystal'||id==='silver_sacred_crystal'){if(h.itemSpellBonus)return false;h.itemSpellBonus=2}else if(id==='bronze_healing_potion'||id==='silver_major_potion'){h.actions--;const amount=id==='bronze_healing_potion'?4:5;h.hp+=Math.min(amount,h.maxHp-h.hp)}else if(id==='bronze_bandage'||id==='silver_purifying_remedy'){if(!removeOneWound(h)&&h.hp>=h.maxHp)return false;h.actions--;h.hp+=Math.min(id==='bronze_bandage'?1:2,h.maxHp-h.hp)}else if(id==='bronze_bomb'||id==='silver_bomb'){if(!aliveEnemies(g).length)return false;h.actions--;const power=id==='bronze_bomb'?2:3;for(const enemy of [...aliveEnemies(g)])damage(g,h.role,enemy,power);checkVictory(g)}else if(id==='bronze_evasion'){h.actions--;h.itemEvasion=true}else if(id==='silver_ward'){h.actions--;h.itemWard=3}else if(id==='silver_revival'){const target=g.party.find(hero=>hero.role===targetRole&&hero.hp<=0)||g.party.find(hero=>hero.hp<=0);if(!target)return false;h.actions--;target.hp=Math.min(3,target.maxHp);boardAudit(g,'HERO_REVIVED_BY_ITEM',{hero:h.role,target:target.role,hp:target.hp})}else return false;consumeBagItem(g,h,slotIndex);note(g,`🎒 ${NAMES[h.role]} usa ${item.name}.`);return true}
function equipmentFromItem(id){const item=TREASURE_ITEMS[id];return{id,name:item.name,damage:item.damage,block:item.block,healingBonus:item.healingBonus,spellDamageBonus:item.spellDamageBonus,holyPulseBonus:item.holyPulseBonus,twoHanded:!!item.twoHanded,power:item.power,itemId:id}}
function storeEquipmentIds(h,slotIndex,ids){h.bag[slotIndex]=null;for(const id of ids){const index=h.bag.findIndex(slot=>!slot);if(index<0)return false;h.bag[index]={item:id,count:1}}return true}
function equipBagItem(g,h,slotIndex,hand='left'){const id=h?.bag?.[slotIndex]?.item,item=TREASURE_ITEMS[id];if(!item||item.kind!=='equipment'||item.role!==h.role||g.state!=='restoring'||h.role!==g.activeRole||h.actions<1||h.role==='warrior'&&item.slot==='offhand'&&h.twoHanded)return false;const next=equipmentFromItem(id),returning=[];if(h.role==='warrior'){if(item.slot==='weapon'){if(h.weapon?.itemId)returning.push(h.weapon.itemId);if(item.twoHanded&&h.offhand?.itemId)returning.push(h.offhand.itemId)}else if(h.offhand?.itemId)returning.push(h.offhand.itemId)}else if(h.role==='healer'){const current=item.slot==='staff'?h.staff:h.wand;if(current?.itemId)returning.push(current.itemId)}else{const current=h.daggers[hand];if(current?.itemId)returning.push(current.itemId)}const available=h.bag.filter((slot,index)=>index===slotIndex||!slot).length;if(returning.length>available)return false;if(!storeEquipmentIds(h,slotIndex,returning))return false;if(h.role==='warrior'){if(item.slot==='weapon'){h.weapon=next;h.twoHanded=next.twoHanded;if(next.twoHanded)h.offhand=null}else h.offhand=next;h.board.equipment=[h.weapon?.id,h.offhand?.id].filter(Boolean)}else if(h.role==='healer'){if(item.slot==='staff')h.staff=next;else h.wand=next}else h.daggers[hand]=next;h.actions--;g.telemetry.items.equipmentChanged++;boardAudit(g,'TREASURE_EQUIPPED',{hero:h.role,item:id,slot:item.slot,hand:h.role==='rogue'?hand:null,actionCost:1,returned:returning});note(g,`✦ ${NAMES[h.role]} equipaggia ${item.name} (1 azione).`);return true}
function bagSlotHtml(h,slot,index,active){if(!slot)return`<div class="hero-bag-slot"><strong>Slot ${index+1}</strong><small>Vuoto</small></div>`;const trash=`<button class="bag-trash" data-trash-item="${index}" data-bag-role="${h.role}" title="Elimina dalla Bag" aria-label="Elimina dallo slot ${index+1}">🗑</button>`,usableState=['playing','restoring'].includes(game.state);if(slot.item==='apple')return`<div class="hero-bag-slot apple"><strong>🍎 ×${slot.count}</strong><small>+2 HP · 1 azione</small><div><button data-eat-apple="${index}" data-bag-role="${h.role}" ${!active||!usableState||h.actions<1||h.hp>=h.maxHp?'disabled':''}>Mangia</button>${trash}</div></div>`;const item=TREASURE_ITEMS[slot.item],free=['bronze_whetstone','bronze_crystal','silver_runestone','silver_sacred_crystal','silver_haste'].includes(slot.item),disabled=!active||!usableState||!free&&h.actions<1,dead=game.party.filter(hero=>hero.hp<=0);if(item.kind==='equipment'){const canEquip=game.state==='restoring'&&active&&h.actions>0,controls=h.role==='rogue'?`<button data-equip-item="${index}" data-equip-hand="left" ${canEquip?'':'disabled'}>Sinistra · 1 azione</button><button data-equip-item="${index}" data-equip-hand="right" ${canEquip?'':'disabled'}>Destra · 1 azione</button>`:`<button data-equip-item="${index}" ${canEquip?'':'disabled'}>Equipaggia · 1 azione</button>`;return`<div class="hero-bag-slot treasure ${item.tier.toLowerCase()}"><strong>${item.name}</strong><small>${item.text}</small><div>${controls}${trash}</div></div>`}const controls=slot.item==='silver_revival'&&dead.length?dead.map(target=>`<button data-use-item="${index}" data-item-target="${target.role}" ${disabled?'disabled':''}>Rialza ${NAMES[target.role]}</button>`).join(''):`<button data-use-item="${index}" ${disabled||slot.item==='silver_revival'?'disabled':''}>Usa</button>`;return`<div class="hero-bag-slot treasure ${item.tier.toLowerCase()}"><strong>${item.name}</strong><small>${item.text}</small><div>${controls}${trash}</div></div>`}
function heroBagPanel(h){const active=h.role===game.activeRole,apples=h.bag.reduce((total,slot)=>total+(slot?.item==='apple'?slot.count:0),0),items=h.bag.filter(slot=>slot&&slot.item!=='apple').length;return`<details class="hero-bag" data-bag-role="${h.role}" ${h.bagOpen?'open':''}><summary><span>Bag</span><span>🍎 ×${apples} · ${items} oggetti · 6 slot</span></summary><div class="bag-slots">${h.bag.map((slot,index)=>bagSlotHtml(h,slot,index,active)).join('')}</div></details>`}
function drawLootItem(g,tier,role=null){if(tier==='GOLD'){const deck=g.lootDecks.GOLD[role];if(!deck.length)deck.push(...shuffle([...GOLD_LOOT_BY_ROLE[role]]));return deck.pop()}const pool=tier==='BRONZE'?BRONZE_LOOT_POOL:SILVER_LOOT_POOL,deck=g.lootDecks[tier];if(!deck.length)deck.push(...shuffle([...pool]));return deck.pop()}
