const attachBoardWithoutTalents=attachBoard;
attachBoard=function(...args){const g=attachBoardWithoutTalents(...args),warrior=g.party.find(h=>h.role==='warrior'),priest=g.party.find(h=>h.role==='healer'),rogue=g.party.find(h=>h.role==='rogue'),mage=g.party.find(h=>h.role==='mage');if(warrior)ensureWarriorTalents(warrior);if(priest)ensurePriestTalents(priest);if(rogue)ensureRogueTalents(rogue);if(mage)ensureMageTalents(mage);for(const h of g.party){h.waitingCards=[];h.pendingPrunes=[];h.bag=Array.from({length:HERO_BAG_SLOTS},(_,index)=>index?null:{item:'apple',count:5});h.heroLevel=1;h.xp=0;h.pendingLevelRewards=0}g.lootDecks={BRONZE:shuffle([...BRONZE_LOOT_POOL]),SILVER:shuffle([...SILVER_LOOT_POOL]),GOLD:{warrior:shuffle([...GOLD_LOOT_BY_ROLE.warrior]),healer:shuffle([...GOLD_LOOT_BY_ROLE.healer]),rogue:shuffle([...GOLD_LOOT_BY_ROLE.rogue])}};const roleCounters=Object.fromEntries(['warrior','healer','rogue','mage'].map(role=>[role,0]));g.telemetry.items={applesEaten:{...roleCounters},appleHealing:{...roleCounters},treasuresOpened:{BRONZE:0,SILVER:0,GOLD:0},lootAssigned:0,lootLeft:0,itemsUsed:{},equipmentChanged:0,discarded:0};g.telemetry.progression={xpPerKill:HERO_KILL_XP,kills:0,xpGranted:{...roleCounters},levelUps:{...roleCounters}};if(priest){priest.divineStrikeCasting=false;priest.holyStrikeCasting=false;priest.staff={id:'staff',name:'Staff',healingBonus:1,itemId:'base_staff'};priest.wand={id:'wand',name:'Wand',damage:1,itemId:'base_wand'}}if(rogue){rogue.evasionFreeFlip=false;rogue.daggers={left:{id:'dagger_left',name:'Dagger Left',damage:1,itemId:'base_dagger'},right:{id:'dagger_right',name:'Dagger Right',damage:1,itemId:'base_dagger'}}}if(warrior){warrior.canEquipTwoHanded=true;warrior.weapon={...WARRIOR_EQUIPMENT.sword};warrior.offhand={...WARRIOR_EQUIPMENT.shield};warrior.twoHanded=false}if(mage){mage.staff={id:'mage_staff',name:'Staff',spellDamageBonus:1};mage.wand={id:'mage_wand',name:'Wand',damage:1};mage.fireballCasting=false}return g};
