checkVictory=function(g){if(g.playerBoardEnabled&&g.state==='playing'&&!aliveEnemies(g).length){if(!aliveHeroes(g).length){g.state='lost';g.telemetry.defeatCause='party_wipe';g.currentEncounter.rounds=g.round;abandon(g);note(g,'✕ Eliminazione simultanea: nessun Eroe può rianimare il gruppo.');return}clearPriestRoomEffects(g)}return legacyCheckVictory(g)};
function setPosition(g,h,card,targetId=null){h.board.position={card,targetId};boardAudit(g,card?'POSITION_SET':'POSITION_CLEARED',{hero:h.role,card,targetId});validateBoard(g)}
function boardInvest(g,h,a){const before=h.mastery[a]||0;if(before>=5)return false;const oldLevel=boardLevel(before),value=before+1,newLevel=boardLevel(value);h.mastery[a]=value;h.levels[a]=newLevel;boardAudit(g,'ENGINE_INVESTED',{hero:h.role,ability:a,from:before,to:value});if(newLevel>oldLevel)boardAudit(g,'ABILITY_LEVEL_UP',{hero:h.role,ability:a,from:oldLevel,to:newLevel});validateBoard(g);return true}
function specializationAffinity(h,card){return h.role==='warrior'?WARRIOR_CARD_AFFINITY[card]||[]:h.role==='healer'?PRIEST_CARD_AFFINITY[card]||[]:[]}
function specializationPruneCandidates(h,opposite){if(h.deck.filter(card=>card!=='wound').length<=SPECIALIZATION_MIN_DECK)return[];const healCount=h.deck.filter(card=>(PRIEST_CARD_AFFINITY[card]||[]).length===1&&PRIEST_CARD_AFFINITY[card][0]==='heal').length;return[...new Set(h.deck.filter(card=>{const affinity=specializationAffinity(h,card);return affinity.length===1&&affinity[0]===opposite&&(h.role!=='healer'||opposite!=='heal'||healCount>PRIEST_MIN_HEALS)}))]}
function queueSpecializationPrune(g,h,talentAffinity=[]){if(talentAffinity.length!==1||!['warrior','healer'].includes(h.role))return false;const branch=talentAffinity[0],opposite=h.role==='warrior'?(branch==='sword'?'shield':'sword'):(branch==='damage'?'heal':'damage');if(!specializationPruneCandidates(h,opposite).length)return false;(h.pendingPrunes??=[]).push({branch,opposite});boardAudit(g,'SPECIALIZATION_PRUNE_OFFERED',{hero:h.role,branch,opposite});return true}
function resolveSpecializationPrune(g,h,card=null){const pending=h.pendingPrunes?.[0];if(!pending)return false;if(card!==null&&!specializationPruneCandidates(h,pending.opposite).includes(card))return false;if(card!==null){const deckIndex=h.deck.indexOf(card);h.deck.splice(deckIndex,1);for(const zone of [h.hand,h.draw,h.discard]){const index=zone.indexOf(card);if(index>=0){zone.splice(index,1);break}}boardAudit(g,'SPECIALIZATION_CARD_RETIRED',{hero:h.role,branch:pending.branch,card,deckSize:h.deck.length});note(g,`⌫ ${NAMES[card]} ritirata dal mazzo di ${NAMES[h.role]}.`)}else boardAudit(g,'SPECIALIZATION_PRUNE_SKIPPED',{hero:h.role,branch:pending.branch});h.pendingPrunes.shift();return true}
function pendingSpecializationPrunes(g){return g.party.some(h=>h.pendingPrunes?.length)}
function ensureWarriorTalents(h){if(!h.talents)h.talents=Object.fromEntries(Object.keys(WARRIOR_TALENTS).map(id=>[id,0]));return h.talents}
function talentAvailable(h,id,rewardCard){ensureWarriorTalents(h);const t=WARRIOR_TALENTS[id],value=h.talents[id]||0,rewardAffinity=WARRIOR_CARD_AFFINITY[rewardCard]||[],talentAffinity=WARRIOR_TALENT_AFFINITY[id]||[];return rewardAffinity.some(icon=>talentAffinity.includes(icon))&&value<t.cost&&(!t.requires||h.talents[t.requires]>=WARRIOR_TALENTS[t.requires].cost)&&(!t.requiresAny||t.requiresAny.some(key=>h.talents[key]>=WARRIOR_TALENTS[key].cost))}
function investWarriorTalent(g,h,id,rewardCard){if(!talentAvailable(h,id,rewardCard))return false;const t=WARRIOR_TALENTS[id];h.talents[id]=(h.talents[id]||0)+1;if(h.talents[id]===t.cost){if(id==='parry_mastery')h.levels.parry=2;if(id==='heroic_mastery')h.levels.sword=2;if(['cleave','shield_slam','whirlwind','improved_critical'].includes(id))for(let copy=0;copy<(['cleave','shield_slam'].includes(id)?2:1);copy++)addDeckCard(h,id==='improved_critical'?'critical':id)}queueSpecializationPrune(g,h,WARRIOR_TALENT_AFFINITY[id]);boardAudit(g,'TALENT_INVESTED',{hero:'warrior',talent:id,card:rewardCard,value:h.talents[id],unlocked:h.talents[id]===t.cost});note(g,`★ ${t.name}: ${h.talents[id]}/${t.cost}${h.talents[id]===t.cost?' · SBLOCCATO':''}.`);return true}
function ensurePriestTalents(h){if(!h.talents)h.talents=Object.fromEntries(Object.keys(PRIEST_TALENTS).map(id=>[id,0]));return h.talents}
function priestTalentAvailable(h,id,rewardCard){ensurePriestTalents(h);const t=PRIEST_TALENTS[id],value=h.talents[id]||0,rewardAffinity=PRIEST_CARD_AFFINITY[rewardCard]||[],talentAffinity=PRIEST_TALENT_AFFINITY[id]||[];return rewardAffinity.some(icon=>talentAffinity.includes(icon))&&value<t.cost&&(!t.requires||h.talents[t.requires]>=PRIEST_TALENTS[t.requires].cost)&&(!t.requiresAny||t.requiresAny.some(key=>h.talents[key]>=PRIEST_TALENTS[key].cost))}
function investPriestTalent(g,h,id,rewardCard){if(!priestTalentAvailable(h,id,rewardCard))return false;const t=PRIEST_TALENTS[id];h.talents[id]=(h.talents[id]||0)+1;if(h.talents[id]===t.cost){const cards=id==='holy_shield'?['holy_shield','holy_shield']:id==='holy_fire'?['holy_fire','holy_fire','holy_fire']:id==='holy_strike'?['holy_strike','holy_strike','holy_strike']:id==='improved_critical'?['critical']:[];cards.forEach(card=>addDeckCard(h,card))}queueSpecializationPrune(g,h,PRIEST_TALENT_AFFINITY[id]);boardAudit(g,'TALENT_INVESTED',{hero:'healer',talent:id,card:rewardCard,value:h.talents[id],unlocked:h.talents[id]===t.cost});note(g,`★ ${t.name}: ${h.talents[id]}/${t.cost}${h.talents[id]===t.cost?' · SBLOCCATO':''}.`);return true}
function ensureRogueTalents(h){if(!h.talents)h.talents=Object.fromEntries(Object.keys(ROGUE_TALENTS).map(id=>[id,0]));return h.talents}
function ensureMageTalents(h){if(!h)return null;if(!h.talents)h.talents=Object.fromEntries(Object.keys(MAGE_TALENTS).map(id=>[id,0]));return h.talents}
function mageTalentAvailable(h,id,rewardCard){ensureMageTalents(h);const t=MAGE_TALENTS[id],value=h.talents[id]||0,rewardAffinity=MAGE_CARD_AFFINITY[rewardCard]||[],talentAffinity=MAGE_TALENT_AFFINITY[id]||[];return rewardAffinity.some(icon=>talentAffinity.includes(icon))&&value<t.cost&&(!t.requires||h.talents[t.requires]>=MAGE_TALENTS[t.requires].cost)}
function investMageTalent(g,h,id,rewardCard){if(!mageTalentAvailable(h,id,rewardCard))return false;const t=MAGE_TALENTS[id];h.talents[id]=(h.talents[id]||0)+1;if(h.talents[id]===t.cost){const cards=id==='frost_armor'?['frost_armor','frost_armor']:id==='cone_of_cold'?['cone_of_cold','cone_of_cold']:id==='living_bomb'?['living_bomb','living_bomb']:id==='fire_piercing'?['fire_piercing','fire_piercing']:[];cards.forEach(card=>addDeckCard(h,card))}boardAudit(g,'TALENT_INVESTED',{hero:'mage',talent:id,card:rewardCard,value:h.talents[id],unlocked:h.talents[id]===t.cost});note(g,`★ ${t.name}: ${h.talents[id]}/${t.cost}${h.talents[id]===t.cost?' · SBLOCCATO':''}.`);return true}
function rogueTalentAvailable(h,id,rewardCard){ensureRogueTalents(h);const t=ROGUE_TALENTS[id],value=h.talents[id]||0,rewardAffinity=ROGUE_CARD_AFFINITY[rewardCard]||[],talentAffinity=ROGUE_TALENT_AFFINITY[id]||[];return rewardAffinity.some(icon=>talentAffinity.includes(icon))&&value<t.cost&&(!t.requires||h.talents[t.requires]>=ROGUE_TALENTS[t.requires].cost)&&(!t.requiresAny||t.requiresAny.some(key=>h.talents[key]>=ROGUE_TALENTS[key].cost))}
function investRogueTalent(g,h,id,rewardCard){if(!rogueTalentAvailable(h,id,rewardCard))return false;const t=ROGUE_TALENTS[id];h.talents[id]=(h.talents[id]||0)+1;if(h.talents[id]===t.cost){const cards=id==='mutilate'?['mutilate','mutilate']:id==='vile_poison'?['vile_poison','vile_poison']:id==='garrote'?Array(4).fill('garrote'):id==='improved_critical'?['critical']:[];cards.forEach(card=>addDeckCard(h,card))}boardAudit(g,'TALENT_INVESTED',{hero:'rogue',talent:id,card:rewardCard,value:h.talents[id],unlocked:h.talents[id]===t.cost});note(g,`★ ${t.name}: ${h.talents[id]}/${t.cost}${h.talents[id]===t.cost?' · SBLOCCATO':''}.`);return true}
function equipWarriorTwoHanded(g,h,weapon=WARRIOR_EQUIPMENT.two_handed_fixture){if(!h.canEquipTwoHanded||!weapon.twoHanded)return false;h.weapon={...weapon};h.offhand=null;h.twoHanded=true;h.board.equipment=[weapon.id];h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;boardAudit(g,'EQUIPMENT_CHANGED',{hero:'warrior',slot:1,item:weapon.id,damage:weapon.damage,slot2Blocked:true});note(g,`⚔ Equipaggiata ${weapon.name}: ${weapon.damage} danni base · slot 2 occupato.`);return true}
