function investWaitingTalent(g,h,id){if(!waitingTalentAvailable(h,id))return false;const target=WARRIOR_TALENT_AFFINITY[id][0],source=target==='sword'?'shield':'sword',synthetic=target==='sword'?'sword':'parry';for(let used=0;used<2;used++){const index=h.waitingCards.findIndex(card=>(WARRIOR_CARD_AFFINITY[card]||[]).includes(source));h.waitingCards.splice(index,1)}const invested=investWarriorTalent(g,h,id,synthetic);if(invested){boardAudit(g,'WAITING_CONVERTED',{hero:'warrior',source,spent:2,talent:id});note(g,`↻ 2 carte ${source==='shield'?'🛡':'⚔'} dalla Riserva → ${WARRIOR_TALENTS[id].name}.`)}return invested}
function waitingPanel(h){if(!h.waitingCards?.length)return'';const icons=card=>(WARRIOR_CARD_AFFINITY[card]||[]).map(icon=>icon==='shield'?'🛡':'⚔').join(''),buttons=Object.keys(WARRIOR_TALENTS).filter(id=>waitingTalentAvailable(h,id)).map(id=>{const target=WARRIOR_TALENT_AFFINITY[id][0],source=target==='sword'?'🛡':'⚔';return`<button data-waiting-talent="${id}">Spendi 2 ${source} → ${WARRIOR_TALENTS[id].name}</button>`}).join('');return`<section class="waiting-panel"><h3>Riserva</h3><div class="waiting-cards">${h.waitingCards.map(card=>`<span>${icons(card)} ${NAMES[card]}</span>`).join('')}</div>${buttons?`<div class="reward-actions">${buttons}</div>`:'<small>Servono due carte dello stesso lato per convertirle nel lato opposto.</small>'}</section>`}
