function investPriestWaitingTalent(g,h,id){if(!priestWaitingTalentAvailable(h,id))return false;const target=PRIEST_TALENT_AFFINITY[id][0],source=target==='heal'?'damage':'heal',synthetic=target==='heal'?'quick_heal':'holy_pulse';for(let used=0;used<2;used++){const index=h.waitingCards.findIndex(card=>(PRIEST_CARD_AFFINITY[card]||[]).includes(source));h.waitingCards.splice(index,1)}const invested=investPriestTalent(g,h,id,synthetic);if(invested){boardAudit(g,'WAITING_CONVERTED',{hero:'healer',source,spent:2,talent:id});note(g,`↻ 2 carte ${source==='heal'?'✚':'✦'} dalla Riserva → ${PRIEST_TALENTS[id].name}.`)}return invested}
function priestWaitingPanel(h){if(!h.waitingCards?.length)return'';const icons=card=>affinityIcons(PRIEST_CARD_AFFINITY[card]),buttons=Object.keys(PRIEST_TALENTS).filter(id=>priestWaitingTalentAvailable(h,id)).map(id=>{const target=PRIEST_TALENT_AFFINITY[id][0],source=target==='heal'?'✦':'✚';return`<button data-priest-waiting-talent="${id}">Spendi 2 ${source} → ${PRIEST_TALENTS[id].name}</button>`}).join('');return`<section class="waiting-panel"><h3>Riserva Priest</h3><div class="waiting-cards">${h.waitingCards.map(card=>`<span>${icons(card)} ${NAMES[card]}</span>`).join('')}</div>${buttons?`<div class="reward-actions">${buttons}</div>`:'<small>Servono due carte Heal o Damage per convertirle nel ramo opposto.</small>'}</section>`}
