function affinityIcons(affinity=[]){return affinity.map(icon=>icon==='shield'?'🛡':icon==='sword'?'⚔':icon==='heal'?'✚':icon==='damage'?'✦':icon==='assassination'?'🗡':'◈').join('')}
function rogueCanPlay(h,card){const stance=h.board.position.card;return card!=='backstab'&&card!=='eviscerate'&&card!=='mutilate'||card==='backstab'&&stance==='BEHIND'||(card==='eviscerate'||card==='mutilate')&&stance==='FRONT'}
function priestCanPlay(h,card){const stance=h.board.position.card;if(card==='holy_pulse'||card==='holy_shield')return true;if(card==='slow_heal'||card==='holy_fire')return stance==='FAR';if(card==='divine_strike'||card==='holy_strike'||card==='bandage')return stance==='NEAR';if(card==='quick_heal')return stance==='NEAR'||h.talents?.divine_reach>=1;return true}
function warriorCanPlay(h,card){const stance=h.board.position.card;if(h.twoHanded&&(card==='parry'||card==='shield_slam'))return false;if(card==='whirlwind')return h.twoHanded&&stance==='AGGRESSIVE';return['sword','cleave'].includes(card)?stance==='AGGRESSIVE':['parry','shield_slam'].includes(card)?stance==='DEFENSIVE':true}
function flipWarrior(g,h){if(!['playing','restoring'].includes(g.state)||h.actions<1)return false;const next=h.board.position.card==='AGGRESSIVE'?'DEFENSIVE':'AGGRESSIVE';h.actions--;h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;g.telemetry.warriorStance.flips++;g.telemetry.warriorStance.actionsSpentOnFlip++;setPosition(g,h,next);note(g,`↔ Warrior passa in ${next} (1 azione).`);return true}
function flipRogue(g,h){const free=g.state==='playing'&&!!h.evasionFreeFlip;if(!['playing','restoring'].includes(g.state)||!free&&h.actions<1||h.preparationPending)return false;const next=h.board.position.card==='FRONT'?'BEHIND':'FRONT';if(free)h.evasionFreeFlip=false;else{h.actions--;g.telemetry.rogue.actionsSpentOnFlip++}h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null;g.telemetry.rogue.flips++;setPosition(g,h,next);note(g,`↔ Rogue passa in ${next} (${free?'gratis con Evasion Tricky':'1 azione'}).`);return true}
function flipPriest(g,h){if(!['playing','restoring'].includes(g.state)||h.actions<1)return false;const next=h.board.position.card==='FAR'?'NEAR':'FAR';h.actions--;g.telemetry.priest.flips++;g.telemetry.priest.actionsSpentOnFlip++;setPosition(g,h,next);note(g,`↔ Priest passa in ${next} (1 azione).`);return true}
function toggleWarriorTechnique(g,h,card,index){if(!['sword','rend','parry','cleave','shield_slam','whirlwind'].includes(card)||h.hand[index]!==card||!warriorCanPlay(h,card)||g.state!=='playing')return false;const same=h.warriorTechniqueArmed===card&&h.warriorTechniqueIndex===index;h.warriorTechniqueArmed=same?null:card;h.warriorTechniqueIndex=same?null:index;const shield=['parry','shield_slam'].includes(card);note(g,h.warriorTechniqueArmed?`◇ ${NAMES[card]} agganciata a ${shield?'Shield':'Weapon'} (0 azioni).`:`○ ${NAMES[card]} rimessa in mano.`);return true}
