function playHolyPulse(g,h){if(g.state!=='playing'||h.actions<1||!h.hand.includes('holy_pulse'))return false;const targets=[...aliveEnemies(g)];if(!targets.length)return false;const critical=h.criticalArmed&&h.hand.includes('critical'),itemBonus=h.itemSpellBonus||0,power=1+priestSpellDamageBonus(h,'holy_pulse')+itemBonus+(critical?1:0);spend(h,'holy_pulse');g.telemetry.actionsPlayed.healer.holy_pulse=(g.telemetry.actionsPlayed.healer.holy_pulse||0)+1;const dealt=targets.reduce((total,target)=>total+damage(g,'healer',target,power),0);if(itemBonus)h.itemSpellBonus=0;if(critical)consumeCritical(g,h,'holy_pulse');boardAudit(g,'HOLY_PULSE_USED',{hero:'healer',targets:targets.map(target=>target.id),valuePerTarget:power,totalValue:dealt,critical,itemBonus});note(g,`✦ Impulso Sacro${critical?' + Critico':''}: ${power} ${power===1?'danno':'danni'} a tutti i nemici.`);checkVictory(g);return true}
