enemyPhase=function(g){if(!g.playerBoardEnabled)return legacyEnemyPhase(g);g.telemetry.taunt.aggroEnemiesRoundTotal+=aliveEnemies(g).filter(e=>e.taunted).length;g.telemetry.taunt.roundsObserved++;for(const e of [...aliveEnemies(g)]){if(!aliveHeroes(g).length)break;resolveEnemyHandActivation(g,e)}checkVictory(g);if(!aliveHeroes(g).length){g.state='lost';g.telemetry.defeatCause='party_wipe';g.currentEncounter.rounds=g.round;g.telemetry.wipeState={encounter:g.encounter+1,round:g.round,enemiesAlive:aliveEnemies(g).length};abandon(g);note(g,'✕ Party sconfitto.')}};
function chooseCommand(cards){return cards.includes('tactic')?'tactic':cards.includes('special')?'special':cards[0]}
function nearHeroes(g){return aliveHeroes(g).filter(h=>h.board?.position.card!=='FAR')}
function resolveEnemyHit(g,target,power,label,evadable=true){if(evadable&&(target.itemEvasion||target.role==='rogue'&&target.evasion)){if(target.itemEvasion)target.itemEvasion=false;else{target.evasion=false;g.telemetry.rogue.evasionPrevented++}note(g,`💨 ${NAMES[target.role]} evita ${label}.`);return{hit:0,prevented:0,evaded:true}}const before=target.hp,{hit,prevented}=preventHeroDamage(target,power);target.hp-=hit;g.telemetry.classContribution[target.role].prevention+=prevented;g.telemetry.classContribution[target.role].damageTaken+=hit;if(before>0&&target.hp<=0)g.telemetry.deaths[target.role]++;return{hit,prevented,evaded:false}}
function resolveEnemyAttack(g,e,target){if(!target)return false;const result=resolveEnemyHit(g,target,e.damage||2,`l’ATTACK di ${enemyLabel(e)}`);if(!result.evaded&&target.counter&&e.hp>0){damage(g,target.role,e,target.counter);target.counter=0}note(g,`☠ ${enemyLabel(e)}: ATTACK, ${result.hit} danni a ${NAMES[target.role]}.`);return true}
function resolveEngineerRepair(g,e,targetId=null){const damaged=aliveEnemies(g).filter(enemy=>enemy.hp<enemy.maxHp),target=damaged.find(enemy=>enemy.id===targetId)||damaged.sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(!target){note(g,`🔧 ${enemyLabel(e)} usa Riparazione, ma nessun nemico è ferito.`);return true}const healed=Math.min(2,target.maxHp-target.hp);target.hp+=healed;note(g,`🔧 ${enemyLabel(e)} ripara ${enemyLabel(target)}: +${healed} HP.`);return true}
function resolveWarchiefAcid(g,e){const targets=nearHeroes(g);g.telemetry.overlordCommand.specialUses++;let total=0;for(const target of targets)total+=resolveEnemyHit(g,target,3,`la Cascata di Acido di ${enemyLabel(e)}`).hit;g.telemetry.overlordCommand.specialDamage+=total;note(g,`🟢 ${enemyLabel(e)} usa Cascata di Acido: 3 danni AOE NEAR a ${targets.map(h=>NAMES[h.role]).join(', ')||'nessun Eroe NEAR'}.`);return true}
function resolveWarchiefOrder(g,e,target){if(!target)return false;g.telemetry.overlordCommand.specialUses++;let total=0;const attackers=aliveEnemies(g).filter(enemy=>enemy!==e),warrior=aliveHeroes(g).find(hero=>hero.role==='warrior');for(const attacker of attackers){if(target.hp<=0)break;const orderedTarget=attacker.taunted&&warrior?.hp>0?warrior:target,before=orderedTarget.hp;resolveEnemyAttack(g,attacker,orderedTarget);total+=Math.max(0,before-orderedTarget.hp)}g.telemetry.overlordCommand.specialDamage+=total;note(g,`⚑ ${enemyLabel(e)} usa Ordine di Guerra: ${attackers.length} alleati attaccano ${NAMES[target.role]}.`);return true}
function resolveEnemyTactic(g,e,target,secondaryTargetId=null){if(e.type==='engineer')return resolveEngineerRepair(g,e,secondaryTargetId);if(e.type==='warchief')return resolveWarchiefCritical(g,e,target);if(!target)return false;const power=PLAYER_BOARD_ENEMIES[e.type].tactic,result=resolveEnemyHit(g,target,power,`la TACTIC di ${enemyLabel(e)}`,false);g.telemetry.overlordCommand.tacticDamage+=result.hit;const wounds=e.type==='miniBoss'?2:1;if(target.hp>0)for(let i=0;i<wounds;i++){target.deck.push('wound');target.draw.push('wound')}note(g,`☣ ${enemyLabel(e)}: TACTIC, ${result.hit} danni + ${wounds} Wound su ${NAMES[target.role]}.`);return true}
function resolveGoblinNearAoe(g,e,targetRoles=[]){const eligible=nearHeroes(g),selected=targetRoles.map(role=>eligible.find(h=>h.role===role)).filter(Boolean).slice(0,2),targets=selected.length?selected:eligible.slice(0,2);g.telemetry.overlordCommand.specialUses++;let total=0;for(const target of targets)total+=resolveEnemyHit(g,target,2,`il Colpo Spazzante di ${enemyLabel(e)}`).hit;g.telemetry.overlordCommand.specialDamage+=total;note(g,`⚔ ${enemyLabel(e)} usa Colpo Spazzante: 2 danni a ${targets.map(h=>NAMES[h.role]).join(' e ')||'nessun Eroe NEAR'}.`);return true}
function resolveMegaBomb(g,e){g.telemetry.overlordCommand.specialUses++;if(!e.megaBombCasting){e.megaBombCasting=true;e.longCast='mega_bomb';e.casting={name:'Mega Bomba',cardsRequired:2};note(g,`💣 ${enemyLabel(e)} prepara Mega Bomba (1/2).`);return true}e.megaBombCasting=false;e.longCast=false;e.casting=null;const power=PLAYER_BOARD_ENEMIES[e.type].special;let total=0;for(const target of aliveHeroes(g)){const result=resolveEnemyHit(g,target,power,`la Mega Bomba di ${enemyLabel(e)}`);total+=result.hit;if(e.type==='miniBoss')g.telemetry.miniBoss.aoeDamage[target.role]+=result.hit}g.telemetry.overlordCommand.specialDamage+=total;if(e.type==='miniBoss')g.telemetry.miniBoss.aoeUses++;note(g,`💥 ${enemyLabel(e)} fa esplodere Mega Bomba: ${power} danni AOE WIDE.`);return true}
function resolveWarchiefCritical(g,e,target){if(!target)return false;const result=resolveEnemyHit(g,target,e.damage+1,`il Colpo Critico di ${enemyLabel(e)}`);g.telemetry.overlordCommand.tacticDamage+=result.hit;if(!result.evaded&&target.counter&&e.hp>0){damage(g,target.role,e,target.counter);target.counter=0}note(g,`✹ ${enemyLabel(e)} usa Colpo Critico: ${result.hit} danni a ${NAMES[target.role]}.`);return true}
function resolveEnemySpecial(g,e,targetRoles=[],target=null){return e.type==='goblin'?resolveGoblinNearAoe(g,e,targetRoles):e.type==='warchief'?resolveWarchiefAcid(g,e):resolveMegaBomb(g,e)}
