function rewardTalentButtons(){return''}

function abilityTrack(h,a){const value=h.mastery[a]||0,level=boardLevel(value),steps=Array.from({length:6},(_,i)=>`<span class="mastery-step ${i===value?'current':''} ${i===2||i===5?'threshold':''}">${i}${i===2?'<small>L2</small>':i===5?'<small>L3</small>':''}</span>`).join(''),texts=ABILITY_TEXT[a]||['TBD','TBD','TBD'];return`<article class="ability-track"><header><strong>${NAMES[a]||a}</strong><b>L${level}</b></header><div class="mastery-line">${steps}</div><ol>${texts.map((t,i)=>`<li class="${i+1===level?'active':''}">L${i+1}: ${t}</li>`).join('')}</ol></article>`}
function playerBoard(h){const cfg=h.board.config,pos=h.board.position,value=`ally:${h.role}:0`,selected=game.selectedTarget===value,active=h.role===game.activeRole,positionControl=h.role==='warrior'?`<button class="flip-position" data-flip="warrior" ${!active||h.actions<1?'disabled':''}>Flip → ${pos.card==='AGGRESSIVE'?'DEFENSIVE':'AGGRESSIVE'} · 1 azione</button>`:h.role==='rogue'?`<button class="flip-position" data-flip="rogue" ${!active||h.actions<1||h.preparationPending?'disabled':''}>Flip → ${pos.card==='FRONT'?'BEHIND':'FRONT'} · 1 azione</button>`:`<button class="flip-position" data-flip="priest" ${!active||h.actions<1?'disabled':''}>Flip → ${pos.card==='FAR'?'NEAR':'FAR'} · 1 azione</button>`,equipmentOne=h.role==='warrior'?`<span>SWORD · 1 danno</span><button class="wand-action" data-sword="warrior" ${!active||h.actions<1||game.state!=='playing'?'disabled':''}>Attacca · 1 azione</button>`:h.role==='healer'?`<span>STAFF · cure +1 · spell damage 1</span>`:`<span>DAGGER LEFT · 1 danno</span><button class="wand-action" data-dagger="left" ${!active||h.actions<1||game.state!=='playing'?'disabled':''}>Attacca · 1 azione</button>`,equipmentTwo=h.role==='warrior'?`<span>SHIELD · +1 Block</span><button class="wand-action" data-shield="warrior" ${!active||h.actions<1||game.state!=='playing'?'disabled':''}>Block · 1 azione</button>`:h.role==='healer'?`<span>WAND · FAR</span><button class="wand-action" data-wand="healer" ${!active||h.actions<1||pos.card!=='FAR'||game.state!=='playing'?'disabled':''}>1 danno · 1 azione</button>`:`<span>DAGGER RIGHT · 1 danno</span><button class="wand-action" data-dagger="right" ${!active||h.actions<1||game.state!=='playing'?'disabled':''}>Attacca · 1 azione</button>`;return`<section class="player-board ${cfg.placeholder?'placeholder':''}"><div class="board-cards"><div class="card-cell art has-portrait"><img class="hero-portrait" src="${heroArt(h)}" alt="${cfg.artwork}"></div><div class="card-cell info-cell"><h2>${cfg.className} — ${cfg.specializationName}</h2><div class="hp-track"><strong>HP ${Math.max(0,h.hp)}/${h.maxHp}</strong><span class="hp-pips">${Array.from({length:h.maxHp},(_,i)=>`<i class="${i<h.hp?'full':''}"></i>`).join('')}</span></div>${xpTrackHtml(h)}<div class="stance-box position-${pos.card?.toLowerCase()||'empty'}"><b>${h.role==='warrior'?'Stance':'Position'}</b><span>${pos.card||'Nessuna'}${pos.targetId?` → ${pos.targetId}`:''}</span>${positionControl}</div></div><div class="card-cell equip-slot" style="--w:url('assets/weapons/${weaponArt(h,0)}.jpeg')"><b>Equipment 1</b>${equipmentOne}</div><div class="card-cell equip-slot" style="--w:url('assets/weapons/${weaponArt(h,1)}.jpeg')"><b>Equipment 2</b>${equipmentTwo}</div></div><div class="mastery-grid">${h.abilities.map(a=>abilityTrack(h,a)).join('')}</div></section>`}
function iconSummary(icons={}){return Object.entries(icons).filter(([,n])=>n).map(([type,n])=>`<span class="tile-icon">${type==='FIGHTER'?'⚔':'◆'} ${n}</span>`).join('')||'<span class="tile-icon">Vuoto</span>'}
const ROOM_ART={"E2-01":"assets/stanza-e2-01.jpeg","E2-02":"assets/stanza-e2-02.jpeg","E2-03":"assets/stanza-e2-03.jpeg","E2-04":"assets/stanza-e2-04.jpeg","E2-05":"assets/stanza-e2-05.jpeg","E2-06":"assets/stanza-e2-06.jpeg","E2-07":"assets/stanza-e2-07.jpeg","E2-08":"assets/stanza-e2-08.jpeg","E2-09":"assets/stanza-e2-09.jpeg","E2-10":"assets/stanza-e2-10.jpeg","SPECIAL-MINI-BOSS":"assets/trono-grumara.jpeg"};
function roomDisplayName(x,room){if(room.depth===0)return'Ingresso';if(room.name)return room.name;return x.config.roomTiles.find(tile=>tile.id===room.tileId)?.name||x.overlordHand.find(tile=>tile.id===room.tileId)?.name||(room.containsMiniBoss?'Il Trono Sommerso di Grum’Arat':`Stanza ${room.depth}`)}
function renderExitChoice(x){if(game.state!=='exit_choice')return'';const room=currentExplorationRoom(x),buttons=room.exits.map(exit=>{const label=exit.id.replace(/^start-/,'');return`<button class="exit-option door-card" data-exit-id="${exit.id}" aria-label="Scegli uscita ${label}"><span class="door-plaque"><strong>Uscita ${label}</strong><span>${iconSummary(exit.icons)}</span></span></button>`}).join('');return`<section class="exit-choice"><h3>Quale uscita prendete?</h3><div class="exit-options">${buttons}</div></section>`}
function renderDungeonMap(x){const node=document.getElementById('dungeonMap'),overlord=document.getElementById('overlordPanel');if(!x){node.hidden=true;overlord.hidden=true;return}node.hidden=false;overlord.hidden=false;const rooms=x.map.rooms.map(room=>`<article class="map-tile ${room.depth===0?'start':''} ${room.id===x.map.currentRoomId?'current':''}"><div class="tile-top"><span class="tile-id">${room.tileId}</span><span class="tile-state">${room.state}</span></div>${room.depth===0?'<strong>INGRESSO</strong>':`<h3>Stanza ${room.depth}</h3><div class="tile-icons">${iconSummary(room.composition?.total)}</div><div class="tile-exits">Uscite: ${(room.exits||[]).map(e=>`${e.id} [${Object.entries(e.icons||{}).filter(([,n])=>n).map(([k,n])=>`${k} ${n}`).join(', ')||'vuota'}]`).join(' · ')||'—'}</div>${room.containsMiniBoss?'<p><strong>MINI BOSS</strong></p>':''}`}</article>`).join('');const hand=x.overlordHand.map(t=>`<div class="hand-tile"><strong>${t.id} · ${t.name||'Room Tile'}</strong><span>${iconSummary(t.contentIcons)}</span><small class="muted">Uscite ${(t.exits||[]).length} · età ${x.tileAge[t.id]||0}</small></div>`).join(''),bleedState=(game.enemies||[]).filter(e=>e.hp>0).map(e=>`<div class="enemy-hand"><strong>${e.type==='miniBoss'?'Mini Boss':`Goblin ${e.id}`}</strong><div>${Array.from({length:3},(_,i)=>`<span class="command-slot ${i<(e.bleedCount||0)?'blocked':''}">${i<(e.bleedCount||0)?'🩸':'COMMAND'}</span>`).join('')}</div><small>${3-(e.bleedCount||0)} Command alla prossima attivazione</small></div>`).join(''),deck=game.commandDeck||{draw:[],discard:[],lastDraw:[]};node.innerHTML=`<div class="map-header"><h2>Mappa / stanza</h2><span class="mode-pill">${x.roomsExplored}/${Math.max(x.config.maxRoomsExplored,x.roomsExplored)}</span></div><div class="map-path">${rooms}</div>`;overlord.innerHTML=`<h2>Overlord Command Deck</h2><p class="target-help">ATTACK ×3: 6 danni · TACTIC ×2: 2 danni + Wound · SPECIAL ×1: AOE 3</p><div class="command-status"><span>Draw ${deck.draw.length}</span><span>Discard ${deck.discard.length}</span></div>${deck.lastDraw.length?`<div class="enemy-hand"><strong>Ultima Command Hand</strong><div>${deck.lastDraw.map(c=>`<span class="enemy-card ${c}">${c.toUpperCase()}</span>`).join('')}</div><small>Scelta: ${deck.lastChoice?.toUpperCase()||'—'}</small></div>`:''}${bleedState}<details><summary>Room Tile disponibili</summary><div class="overlord-hand">${hand}</div></details>`}
const renderDungeonMapBase=renderDungeonMap;
renderDungeonMap=function(x){renderDungeonMapBase(x);if(!x)return;document.querySelectorAll('.map-tile').forEach((tile,index)=>{const room=x.map.rooms[index],heading=tile.querySelector('h3'),boss=tile.querySelector('p strong'),art=ROOM_ART[room?.tileId];if(art){tile.classList.add('illustrated-room');tile.style.setProperty('--room-art',`url('${art}')`)}if(boss)boss.textContent='GRUMARA';if(heading&&room){heading.textContent=roomDisplayName(x,room);const label=document.createElement('small');label.className='room-number';label.textContent=`STANZA ${room.depth}`;heading.before(label)}});const choice=renderExitChoice(x);if(choice)document.querySelector('#dungeonMap .map-path').insertAdjacentHTML('afterend',choice)};
const renderDungeonMapWithCommandValues=renderDungeonMap;
renderDungeonMap=function(x){renderDungeonMapWithCommandValues(x);const help=document.querySelector('#overlordPanel .target-help');if(help)help.textContent='GOBLIN — ATTACK ×3: 2 danni · TACTIC ×2: 1 danno + Wound · SPECIAL ×1: 3 danni a tutti'};
const renderDungeonMapWithConnections=renderDungeonMap;
renderDungeonMap=function(x){renderDungeonMapWithConnections(x);if(!x?.config.connectionPlacement)return;document.querySelectorAll('.map-tile').forEach((node,index)=>{const room=x.map.rooms[index],icons=node.querySelector('.tile-icons');if(icons&&room?.composition?.connector)icons.innerHTML=node.classList.contains('illustrated-room')?iconSummary(room.composition.total):`<span class="connection-equation">Uscita ${iconSummary(room.composition.exit)} + lato ${room.entryConnectorId} ${iconSummary(room.composition.connector)} = ${iconSummary(room.composition.total)}</span>`});document.querySelectorAll('#overlordPanel .hand-tile').forEach((node,index)=>{const tile=x.overlordHand[index],summary=node.querySelector('span'),meta=node.querySelector('small');if(summary&&tile)summary.innerHTML=`Lati: ${roomTileConnectors(tile).map(side=>`${side.id} ${iconSummary(side.icons)}`).join(' · ')}`;if(meta&&tile)meta.textContent=`${roomTileConnectors(tile).length} lati · età ${x.tileAge[tile.id]||0}`})};
const renderDungeonMapWithEnemyTypes=renderDungeonMap;
renderDungeonMap=function(x){renderDungeonMapWithEnemyTypes(x);const help=document.querySelector('#overlordPanel .target-help');if(help)help.textContent='RAZZIATORE RANIDE: Attack 3 · Tactic 2 + Wound · Special NEAR 2×2 | ARTIFICIERE RANIDE: Attack 2 · Ripara 2 · Mega Bomba 5 | RANA WARCHIEF: Attack 4 · Critico 5 · Cascata Acido 3 AOE NEAR | GRUMARA: Attack 6 · Tactic 3 + 2 Wound · Mega Bomba 5';const panels=[...document.querySelectorAll('#overlordPanel .enemy-hand')].filter(node=>node.querySelector('.command-slot')),enemies=aliveEnemies(game);panels.forEach((panel,index)=>{const e=enemies[index];if(!e)return;panel.querySelector('strong').textContent=enemyLabel(e);const status=panel.querySelector('small');if(e.type==='miniMob'){panel.querySelector('div').innerHTML='<span class="enemy-card attack">ATTACK 1</span>';status.textContent='Attacco fisso: non pesca Command'}else if(e.megaBombCasting)status.textContent=`${3-(e.bleedCount||0)} Command · Mega Bomba 1/2`})};
function validTarget(g,value){if(!value)return false;return !!targetOf(g,value)&&((value.startsWith('ally:')&&aliveHeroes(g).includes(targetOf(g,value)))||(value.startsWith('enemy:')&&aliveEnemies(g).includes(targetOf(g,value))))}
function renderRoomTargets(g){if(!validTarget(g,g.selectedTarget)){const first=aliveEnemies(g)[0];g.selectedTarget=first?`enemy:x:${first.id}`:`ally:${aliveHeroes(g)[0]?.role||'warrior'}:0`}const enemies=aliveEnemies(g);document.getElementById('enemies').innerHTML=`<h2>Nemici nella stanza</h2><p class="target-help">Scegli direttamente chi bersagliare. La selezione resta attiva dopo ogni carta.</p><div class="room-targets">${enemies.map(e=>{const value=`enemy:x:${e.id}`,selected=g.selectedTarget===value,activation=e.type==='miniMob'?'Attacco fisso 1':`Command ${3-(e.bleedCount||0)}`,casting=e.megaBombCasting?' · 💣 Mega Bomba 1/2':'';return`<button class="room-target ${selected?'selected':''}" data-target="${value}">${selected?'<span class="target-check">✓ TARGET</span>':''}<strong>${enemyLabel(e)}</strong><small>${Math.max(0,e.hp)}/${e.maxHp} PV · ${activation}</small><div class="status-row">${e.bleedCount?`<span class="st st-bleed"><i class="st-ic" style="background-image:url('assets/icons/rend.svg')"></i>${e.bleedCount}/3</span>`:''}${e.holyFireDots?`<span class="st st-holy"><i class="st-ic" style="background-image:url('assets/icons/holy_fire.svg')"></i>${e.holyFireDots}/3</span>`:''}${e.vilePoison?`<span class="st st-poison"><i class="st-ic" style="background-image:url('assets/icons/vile_poison.svg')"></i>${e.vilePoison}</span>`:''}${e.garrote?`<span class="st st-garrote"><i class="st-ic" style="background-image:url('assets/icons/garrote.svg')"></i>${e.garrote}</span>`:''}${e.taunted?`<span class="st st-aggro"><i class="st-ic" style="background-image:url('assets/icons/taunt.svg')"></i></span>`:''}${e.megaBombCasting?`<span class="st st-cast">💣 1/2</span>`:''}</div></button>`}).join('')||'<span class="muted">Nessun nemico vivo.</span>'}</div>`;const hidden=document.getElementById('target');hidden.value=g.selectedTarget}
function bindTargetButtons(){document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{game.selectedTarget=b.dataset.target;render()});document.querySelectorAll('[data-exit-id]').forEach(button=>button.onclick=()=>{choosePlayerExit(game,button.dataset.exitId);render()})}
function handButton(h,hi,c,i){const turnLocked=h.role!==game.activeRole;if(h.role==='rogue'&&h.preparationPending){const canDiscard=!turnLocked&&c!=='wound'&&c!=='critical';return`<button class="action ${c} ${canDiscard?'discard-choice':''}" data-discard="${i}" data-rogue="${hi}" ${canDiscard?'':'disabled'}>${canDiscard?'Scarta: ':''}${NAMES[c]}<small>${c==='wound'?'Wound non scartabile':c==='critical'?'Critico non è una Ability':`Scelte rimaste: ${h.preparationPending}`}</small></button>`}if(h.role==='warrior'&&['sword','rend','parry'].includes(c)){const locked=!warriorCanPlay(h,c),armed=h.warriorTechniqueArmed===c&&h.warriorTechniqueIndex===i,required=c==='parry'?'DEFENSIVE':'AGGRESSIVE';return`<button class="action ${c} ${armed?'armed':''} ${locked?'stance-locked':''}" data-war-tech="${i}" data-warrior="${hi}" ${turnLocked||locked||game.state!=='playing'?'disabled':''}>${armed?'✓ ':''}${NAMES[c]}<small>${locked?`Richiede ${required}`:armed?`Agganciata a ${c==='parry'?'Shield':'Sword'} · 0 azioni`:`Technique su ${c==='parry'?'Shield':'Sword'} · 0 azioni`}</small></button>`}if(h.role==='rogue'&&['backstab','eviscerate'].includes(c)){const locked=!rogueCanPlay(h,c),armed=h.rogueTechniqueArmed===c&&h.rogueTechniqueIndex===i,required=c==='backstab'?'BEHIND':'FRONT',description=c==='backstab'?'Dagger +2 · 0 azioni':'Dagger +1 · +2 sotto 50% · 0 azioni';return`<button class="action ${c} ${armed?'armed':''} ${locked?'stance-locked':''}" data-rogue-tech="${i}" data-rogue="${hi}" ${turnLocked||locked||game.state!=='playing'?'disabled':''}>${armed?'✓ ':''}${NAMES[c]}<small>${locked?`Richiede ${required}`:armed?'Agganciata al prossimo Dagger · 0 azioni':description}</small></button>`}if(c==='critical')return`<button class="action critical ${h.criticalArmed?'armed':''}" data-critical="${hi}" ${turnLocked||game.state!=='playing'?'disabled':''}>${h.criticalArmed?'✓ ':''}Critico<small>${h.criticalArmed?'Pronto: scegli una Base Action compatibile':'Modifier · 0 azioni'}</small></button>`;const stanceLocked=h.role==='healer'&&!priestCanPlay(h,c),required=c==='slow_heal'?'FAR':'NEAR',disabled=turnLocked||c==='wound'||h.actions<=0||game.state!=='playing'||stanceLocked;return`<button class="action ${c} ${stanceLocked?'stance-locked':''}" data-h="${hi}" data-i="${i}" ${disabled?'disabled':''}>${NAMES[c]}<small>${turnLocked?'In attesa del turno':stanceLocked?`Richiede ${required}`:DESC[c]}</small></button>`}

function overlordColumn(g){const active=g.activeRole==='overlord',turn=g.overlordTurn,e=g.enemies.find(enemy=>enemy.id===turn?.enemyId),targetRole=turn?.forcedTargetRole||turn?.targetRole,targets=active&&!turn?.forcedTargetRole?aliveHeroes(g).map(h=>`<button class="overlord-target ${targetRole===h.role?'selected':''}" data-overlord-target="${h.role}">${NAMES[h.role]} · ${Math.max(0,h.hp)} HP</button>`).join(''):turn?.forcedTargetRole?`<div class="aggro-lock">🛡 Aggro → ${NAMES[turn.forcedTargetRole]}</div>`:'',counts=Object.fromEntries((turn?.cards||[]).map(card=>[card,(turn.cards||[]).filter(x=>x===card).length])),cards=Object.entries(counts).map(([card,count])=>{const text=card==='attack'?`${e?.damage||6} danni`:card==='tactic'?'2 danni + Wound':'3 danni a tutti',disabled=card!=='special'&&!targetRole;return`<button class="command-choice ${card}" data-overlord-command="${card}" ${disabled?'disabled':''}><strong>${card.toUpperCase()}${count>1?` ×${count}`:''}</strong><small>${text}</small></button>`}).join('');return`<section class="hero-column overlord-column ${active?'active-turn':'waiting-turn'}"><div class="hero"><h2>${active?'<span class="turn-marker">▶ TURNO</span> ':''}Overlord</h2>${active&&e?`<div class="overlord-active-enemy"><strong>${e.type==='miniBoss'?'Mini Boss':`Goblin ${e.id}`}</strong><small>Bleed ${e.bleedCount||0}/3 · scegli target e Command</small></div><div class="overlord-targets">${targets}</div><div class="overlord-cards">${cards}</div>`:`<p class="muted">In attesa · ${aliveEnemies(g).length} nemici · Command ${g.commandDeck?.draw.length||0}/${g.commandDeck?.discard.length||0}</p>`}</div></section>`}
const overlordColumnWithCommandValues=overlordColumn;
overlordColumn=function(g){return overlordColumnWithCommandValues(g).replace('2 danni + Wound','1 danno + Wound')};

function goblinAoeChoices(g){const heroes=nearHeroes(g),pairs=[];for(let first=0;first<heroes.length;first++)for(let second=first+1;second<heroes.length;second++)pairs.push([heroes[first],heroes[second]]);return pairs.length?pairs:heroes.length?[heroes]:[[]]}
overlordColumn=function(g){
  const active=g.activeRole==='overlord',turn=g.overlordTurn,e=g.enemies.find(enemy=>enemy.id===turn?.enemyId),targetRole=turn?.forcedTargetRole||turn?.targetRole;
  const targets=active&&!turn?.forcedTargetRole?aliveHeroes(g).map(h=>`<button class="overlord-target ${targetRole===h.role?'selected':''}" data-overlord-target="${h.role}">${NAMES[h.role]} · ${Math.max(0,h.hp)} HP</button>`).join(''):turn?.forcedTargetRole?`<div class="aggro-lock">🛡 Aggro → ${NAMES[turn.forcedTargetRole]}</div>`:'';
  const counts=Object.fromEntries((turn?.cards||[]).map(card=>[card,(turn.cards||[]).filter(value=>value===card).length]));
  const cards=Object.entries(counts).map(([card,count])=>{
    if(card==='special'&&e?.type==='goblin')return goblinAoeChoices(g).map(pair=>`<button class="command-choice special" data-overlord-command="special" data-overlord-targets="${pair.map(h=>h.role).join(',')}"><strong>SPECIAL${count>1?` ×${count}`:''}</strong><small>Colpo Spazzante · 2 danni a ${pair.map(h=>NAMES[h.role]).join(' + ')||'nessun Eroe NEAR'}</small></button>`).join('');
    const needsTarget=card==='attack'||card==='minion_attack'||card==='tactic'&&e?.type!=='engineer'||card==='special'&&e?.type==='warchief',label=card==='minion_attack'?'ATTACK':card.toUpperCase();
    const text=card==='minion_attack'?'1 danno':card==='attack'?`${e?.damage||2} danni`:card==='tactic'?e?.type==='engineer'?'Ripara 2 HP al nemico più ferito':e?.type==='warchief'?'Colpo Critico · 5 danni':`${PLAYER_BOARD_ENEMIES[e.type].tactic} danni + Wound`:e?.type==='warchief'?`Ordine di Guerra · gli altri ${Math.max(0,aliveEnemies(g).length-1)} nemici attaccano il target`:e?.megaBombCasting?`Detona Mega Bomba · AOE WIDE ${PLAYER_BOARD_ENEMIES[e.type].special}`:'Prepara Mega Bomba · Cast Lungo 1/2';
    return`<button class="command-choice ${card}" data-overlord-command="${card}" ${needsTarget&&!targetRole?'disabled':''}><strong>${label}${count>1?` ×${count}`:''}</strong><small>${text}</small></button>`
  }).join('');
  return`<section class="hero-column overlord-column ${active?'active-turn':'waiting-turn'}"><div class="hero"><h2>${active?'<span class="turn-marker">▶ TURNO</span> ':''}Overlord</h2>${active&&e?`<div class="overlord-active-enemy"><strong>${enemyLabel(e)}</strong><small>${e.type==='miniMob'?'Attacco fisso 1':`Bleed ${e.bleedCount||0}/3 · scegli target e Command`}${e.megaBombCasting?' · 💣 Mega Bomba 1/2':''}</small></div><div class="overlord-targets">${targets}</div><div class="overlord-cards">${cards}</div>`:`<p class="muted">In attesa · ${aliveEnemies(g).length} nemici · Command ${g.commandDeck?.draw.length||0}/${g.commandDeck?.discard.length||0}</p>`}</div></section>`
};

const handButtonWithoutTalentCards=handButton;
handButton=function(h,hi,c,i){
  if(game.state==='restoring'){const usable=h.role==='healer'&&['quick_heal','slow_heal','bandage'].includes(c),locked=usable&&!priestCanPlay(h,c),enabled=usable&&!locked&&h.role===game.activeRole&&h.actions>0;return`<button class="action ${c} ${locked?'stance-locked':''}" data-h="${hi}" data-i="${i}" ${enabled?'':'disabled'}>${NAMES[c]}<small>${locked?`Richiede ${c==='slow_heal'?'FAR':'NEAR'}`:usable?'Recupero · 1 azione':'Non utilizzabile durante il Recupero'}</small></button>`}
  if(h.role==='warrior'&&['sword','rend','parry','cleave','shield_slam','whirlwind'].includes(c)){const shield=['parry','shield_slam'].includes(c),whirlwindCost=h.weapon?.power==='whirlwind_fast'?2:3,cost=c==='whirlwind'?whirlwindCost:1,locked=!warriorCanPlay(h,c)||h.actions<cost,required=shield?'DEFENSIVE':'AGGRESSIVE',weaponDamage=h.weapon?.damage||1,heroicDamage=weaponDamage+(h.talents?.heroic_mastery>=2?2:1),parryBlock=(h.offhand?.block||1)+(h.talents?.parry_mastery>=2?2:1),rendDamage=weaponDamage+(h.talents?.improved_rend||0),description=c==='sword'?`${heroicDamage} danni`:c==='rend'?`${rendDamage} ${rendDamage===1?'danno':'danni'} · Bleed`:c==='parry'?`${parryBlock} Block`:c==='cleave'?'2 danni a tutti':c==='shield_slam'?'3 danni · Interrompe Cast Lunghi':`Danno arma a tutti · ${whirlwindCost} azioni`;return`<button class="action ${c} ${locked?'stance-locked':''}" data-war-tech="${i}" data-warrior="${hi}" ${h.role!==game.activeRole||locked||game.state!=='playing'?'disabled':''}>${NAMES[c]}<small>${locked?c==='whirlwind'&&!h.twoHanded?'Richiede arma a due mani':c==='whirlwind'&&h.actions<whirlwindCost?`Richiede ${whirlwindCost} azioni`:`Richiede ${h.twoHanded&&shield?'Scudo':required}`:description}</small></button>`}
  if(h.role==='healer'&&['holy_shield','holy_fire','divine_strike','holy_strike'].includes(c)){const locked=!priestCanPlay(h,c),required=c==='holy_fire'?'FAR':c==='divine_strike'||c==='holy_strike'?'NEAR':'ANY',casting=(c==='divine_strike'&&h.divineStrikeCasting)||(c==='holy_strike'&&h.holyStrikeCasting);return`<button class="action ${c} ${locked?'stance-locked':''}" data-h="${hi}" data-i="${i}" ${h.role!==game.activeRole||locked||h.actions<1||game.state!=='playing'?'disabled':''}>${NAMES[c]}<small>${locked?`Richiede ${required}`:casting?`Completa il Cast Lungo · ${c==='holy_strike'?4:2} danni`:DESC[c]}</small></button>`}
  if(h.role==='rogue'&&['backstab','eviscerate'].includes(c)){const locked=!rogueCanPlay(h,c)||h.actions<1,description=c==='backstab'?`${3+(h.talents?.improved_backstab>=2?2:0)} danni`:'2 danni · 3 sotto 50%';return`<button class="action ${c} ${locked?'stance-locked':''}" data-rogue-tech="${i}" data-rogue="${hi}" ${h.role!==game.activeRole||locked||game.state!=='playing'?'disabled':''}>${NAMES[c]}<small>${locked?`Richiede ${c==='backstab'?'BEHIND':'FRONT'}`:description}</small></button>`}
  if(h.role==='rogue'&&['mutilate','vile_poison','garrote'].includes(c)){const locked=!rogueCanPlay(h,c),description=c==='mutilate'?`${3+(h.talents?.improved_mutilate>=2?2:0)} danni`:c==='vile_poison'?'DoT 1 cumulativo':'DoT 2 cumulativo';return`<button class="action ${c} ${locked?'stance-locked':''}" data-h="${hi}" data-i="${i}" ${h.role!==game.activeRole||locked||h.actions<1||game.state!=='playing'?'disabled':''}>${NAMES[c]}<small>${locked?'Richiede FRONT':description}</small></button>`}
  if(h.role==='mage'&&MAGE_CARD_AFFINITY[c]){const required=mageRequiredPosition(c),locked=!mageCanPlay(h,c),needsAction=c!=='blink',disabled=h.role!==game.activeRole||locked||needsAction&&h.actions<1||game.state!=='playing';return`<button class="action ${c} ${locked?'stance-locked':''}" data-h="${hi}" data-i="${i}" ${disabled?'disabled':''}>${NAMES[c]}<small>${locked?`Richiede ${required}`:c==='fireball'&&h.fireballCasting?'Completa il Cast Lungo':DESC[c]}</small></button>`}
  if(c==='critical')return`<button class="action critical ${h.criticalArmed?'armed':''}" data-critical="${hi}" ${h.role!==game.activeRole||game.state!=='playing'?'disabled':''}>${h.criticalArmed?'✓ ':''}Critico<small>${h.criticalArmed?'Pronto':'+1'}</small></button>`
  return handButtonWithoutTalentCards(h,hi,c,i)
};

const renderBeforeBoard=render;
render=function(){renderBeforeBoard();renderDungeonMap(game.exploration);const setup=document.getElementById('boardSetup'),enabled=!!game.playerBoardEnabled;document.body.classList.toggle('player-board-active',enabled);if(setup)setup.dataset.active=enabled?'true':'false';if(enabled){const totalRooms=Math.max(game.exploration?.config.maxRoomsExplored||0,game.sequence.length),encounterStat=document.querySelectorAll('#raidStats .stat strong')[1];if(encounterStat)encounterStat.textContent=`${Math.min(game.encounter+1,totalRooms)}/${totalRooms}`;renderRoomTargets(game);document.getElementById('raidStats').innerHTML+=`<div class="stat turn-stat">Turno<strong>${game.activeRole==='enemies'?'Nemici':NAMES[game.activeRole]||'—'}</strong></div>`}if(enabled&&game.state!=='reward'&&game.state!=='treasure'){document.getElementById('party').innerHTML=`<div class="hero-columns">${game.party.map((h,hi)=>`<section class="hero-column ${h.role===game.activeRole?'active-turn':'waiting-turn'}"><div class="hero"><h2>${h.role===game.activeRole?'<span class="turn-marker">▶ TURNO</span> ':''}Mano — ${NAMES[h.role]} <small class="muted">· ${h.actions} azioni · deck ${h.deck.length}</small></h2><div class="hand">${h.hand.map((c,i)=>handButton(h,hi,c,i)).join('')}</div></div>${playerBoard(h)}</section>`).join('')}</div>`;document.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{const h=game.party[+b.dataset.h],card=h.hand[+b.dataset.i],played=play(game,h,card,game.selectedTarget);if(!played)note(game,'Giocata non valida per il bersaglio o il timing scelto.');else advanceHeroTurn(game);render()});document.querySelectorAll('[data-war-tech]').forEach(b=>b.onclick=()=>{const h=game.party[+b.dataset.warrior],card=h.hand[+b.dataset.warTech];toggleWarriorTechnique(game,h,card,+b.dataset.warTech);render()});document.querySelectorAll('[data-rogue-tech]').forEach(b=>b.onclick=()=>{const h=game.party[+b.dataset.rogue],card=h.hand[+b.dataset.rogueTech];toggleRogueTechnique(game,h,card,+b.dataset.rogueTech);render()});document.querySelectorAll('[data-critical]').forEach(b=>b.onclick=()=>{toggleCritical(game,game.party[+b.dataset.critical]);render()});document.querySelectorAll('[data-discard]').forEach(b=>b.onclick=()=>{const h=game.party[+b.dataset.rogue];discardPreparation(game,h,+b.dataset.discard);advanceHeroTurn(game);render()});document.querySelectorAll('[data-flip]').forEach(b=>b.onclick=()=>{const role=b.dataset.flip==='priest'?'healer':b.dataset.flip,h=game.party.find(x=>x.role===role),flip=role==='warrior'?flipWarrior:role==='healer'?flipPriest:flipRogue;flip(game,h);advanceHeroTurn(game);render()});document.querySelectorAll('[data-sword]').forEach(b=>b.onclick=()=>{const h=game.party.find(x=>x.role==='warrior');useSword(game,h,game.selectedTarget);advanceHeroTurn(game);render()});document.querySelectorAll('[data-shield]').forEach(b=>b.onclick=()=>{const h=game.party.find(x=>x.role==='warrior');useShield(game,h);advanceHeroTurn(game);render()});document.querySelectorAll('[data-dagger]').forEach(b=>b.onclick=()=>{const h=game.party.find(x=>x.role==='rogue');useDagger(game,h,game.selectedTarget,b.dataset.dagger);advanceHeroTurn(game);render()});document.querySelectorAll('[data-wand]').forEach(b=>b.onclick=()=>{const h=game.party.find(x=>x.role==='healer');useWand(game,h,game.selectedTarget);advanceHeroTurn(game);render()});bindTargetButtons()}const end=document.getElementById('end');if(enabled&&end){const h=game.party.find(hero=>hero.role===game.activeRole);end.textContent=h?`Passa · ${NAMES[h.role]}`:'Turno nemici';end.disabled=game.state!=='playing'||!h||!!h.preparationPending}if(enabled){validateBoard(game);document.getElementById('telemetry').textContent=JSON.stringify({...game.telemetry,playerBoardAudit:game.playerBoardAudit},null,2)}};

function organizePages(){const main=document.querySelector('main'),title=main.querySelector('h1'),intro=title.nextElementSibling,setup=document.getElementById('boardSetup'),oldGrid=main.querySelector('.grid'),left=oldGrid.querySelector('section'),right=oldGrid.querySelector('aside'),combat=left.children[0],map=document.getElementById('dungeonMap'),bags=document.getElementById('bagMemory'),party=document.getElementById('party'),controls=left.querySelector('.card:last-child'),cards=[...right.querySelectorAll('.card')],logCard=cards.find(c=>c.querySelector('#log')),simulationCard=cards.find(c=>c.querySelector('#results')),telemetry=document.getElementById('telemetry').parentElement;const header=document.createElement('header');header.className='app-header';header.innerHTML=`<h1>Le Paludi della Luna Avvelenata</h1><nav class="page-tabs"><button class="page-tab active" data-page="gamePage">Gioca</button><button class="page-tab" data-page="labPage">Simulazione &amp; test</button></nav>`;const gamePage=document.createElement('section');gamePage.id='gamePage';gamePage.className='app-page';const gameLayout=document.createElement('div');gameLayout.className='game-layout';const playColumn=document.createElement('div');playColumn.className='play-column';const battlefield=document.createElement('div');battlefield.className='battlefield';battlefield.append(combat,map);playColumn.append(battlefield,party);controls.classList.add('game-controls');playColumn.append(controls);const sidebar=document.createElement('aside');sidebar.className='game-sidebar';const overlord=document.createElement('section');overlord.id='overlordPanel';overlord.className='overlord-panel';sidebar.append(overlord,bags,logCard);gameLayout.append(playColumn,sidebar);gamePage.append(setup,gameLayout);const labPage=document.createElement('section');labPage.id='labPage';labPage.className='app-page';labPage.hidden=true;const labShell=document.createElement('div');labShell.className='lab-shell';labShell.append(simulationCard,telemetry);labPage.append(labShell);main.replaceChildren(header,gamePage,labPage);intro.remove();document.querySelectorAll('.page-tab').forEach(button=>button.onclick=()=>{document.querySelectorAll('.page-tab').forEach(x=>x.classList.toggle('active',x===button));gamePage.hidden=button.dataset.page!=='gamePage';labPage.hidden=button.dataset.page!=='labPage'});return setup}
const renderWithoutTalentPage=render;
render=function(){renderWithoutTalentPage();if(!game.playerBoardEnabled)return;const warrior=game.party.find(h=>h.role==='warrior'),priest=game.party.find(h=>h.role==='healer');if(warrior)ensureWarriorTalents(warrior);if(priest)ensurePriestTalents(priest);if(game.state==='reward'){document.getElementById('party').innerHTML=game.pendingRewards.map((r,i)=>`<section class="hero reward-card"><h2>Ricompensa ${NAMES[r.hero.role]}</h2><p><strong>${NAMES[r.ability]}</strong>: scegli frequenza o talento.</p><div class="reward-actions"><button data-reward="${i}" data-choice="deck">Aggiungi ${NAMES[r.ability]} al deck</button>${rewardTalentButtons(r.hero,r.ability,i)}${!['warrior','healer'].includes(r.hero.role)?`<button data-reward="${i}" data-choice="upgrade">Investi nell'abilità</button>`:''}</div>${r.hero.role==='warrior'?warriorTalentPage(r.hero):r.hero.role==='healer'?priestTalentPage(r.hero):''}</section>`).join('');document.querySelectorAll('[data-reward]').forEach(button=>button.onclick=()=>{claimReward(game,+button.dataset.reward,button.dataset.choice);render()});return}for(const [hero,page]of [[warrior,warriorTalentPage],[priest,priestTalentPage]]){if(!hero)continue;const column=[...document.querySelectorAll('.hero-column')].find(node=>node.querySelector('h2')?.textContent.includes(NAMES[hero.role])),board=column?.querySelector('.player-board');if(board&&!board.querySelector('.talent-page'))board.insertAdjacentHTML('beforeend',page(hero))}const warriorColumn=[...document.querySelectorAll('.hero-column')].find(node=>node.querySelector('h2')?.textContent.includes(NAMES.warrior)),warriorBoard=warriorColumn?.querySelector('.player-board');if(warrior?.twoHanded&&warriorBoard){const slots=warriorBoard.querySelectorAll('.board-slots>div');slots[0].innerHTML='<b>Equipment 1</b><span>ARMA A DUE MANI · 3 danni</span><button class="wand-action" data-sword="warrior">Attacca · 1 azione</button>';slots[1].innerHTML='<b>Equipment 2</b><span>Occupato dall’arma a due mani</span>'}document.querySelectorAll('[data-shield]').forEach(button=>button.onclick=()=>{useShield(game,warrior,game.selectedTarget);advanceHeroTurn(game);render()});document.querySelectorAll('[data-sword]').forEach(button=>button.onclick=()=>{useSword(game,warrior,game.selectedTarget);advanceHeroTurn(game);render()})};

