function useMageWand(g,h,targetValue){if(g.state!=='playing'||h.actions<1||h.board.position.card!=='FAR')return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target))return false;h.actions--;const dealt=damage(g,'mage',target,1);g.telemetry.mage.damage+=dealt;note(g,`✦ Wand: ${dealt} danno.`);checkVictory(g);return true}
const renderBeforeMage=render;
render=function(){renderBeforeMage();if(!game?.playerBoardEnabled)return;const mage=game.party.find(h=>h.role==='mage');if(mage&&game.state!=='reward'){const column=[...document.querySelectorAll('.hero-column')].find(node=>node.querySelector('h2')?.textContent.includes(NAMES.mage)),board=column?.querySelector('.player-board');board?.querySelector('.mastery-grid')?.remove();if(board&&!board.querySelector('.talent-page'))board.insertAdjacentHTML('beforeend',mageTalentPage(mage));const page=board?.querySelector('.talent-page');if(page)page.ontoggle=()=>mage.talentsOpen=page.open;const flip=column?.querySelector('[data-flip="mage"]');if(flip)flip.onclick=()=>{flipMage(game,mage);advanceHeroTurn(game);render()};const wand=column?.querySelector('[data-mage-wand]');if(wand)wand.onclick=()=>{useMageWand(game,mage,game.selectedTarget);advanceHeroTurn(game);render()}}if(game.state==='reward'){game.pendingRewards.forEach((reward,index)=>{if(reward.hero.role!=='mage')return;const section=document.querySelector(`[data-reward="${index}"]`)?.closest('.reward-card');if(!section)return;section.querySelector('[data-choice="upgrade"]')?.remove();if(!section.querySelector('.talent-page'))section.insertAdjacentHTML('beforeend',mageTalentPage(reward.hero));section.querySelectorAll('[data-reward]').forEach(button=>button.onclick=()=>{claimReward(game,+button.dataset.reward,button.dataset.choice);render()})})}const container=document.querySelector('.hero-columns');if(container&&game.state==='playing'){const roles=[...(game.turnOrder||game.party.map(h=>h.role)),'overlord'],start=Math.max(0,roles.indexOf(game.activeRole)),columns=[...container.children],find=role=>role==='overlord'?columns.find(c=>c.classList.contains('overlord-column')):columns.find(c=>c.querySelector('h2')?.textContent.includes(NAMES[role]));[...roles.slice(start),...roles.slice(0,start)].forEach(role=>{const column=find(role);if(column)container.append(column)})}};
function specializationPrunePanel(h){const pending=h.pendingPrunes[0],cards=specializationPruneCandidates(h,pending.opposite),branch=h.role==='warrior'?(pending.branch==='sword'?'Aggressive':'Defense'):(pending.branch==='damage'?'Damage':'Heal');return`<section class="hero reward-card specialization-prune"><h2>Sfoltimento — ${NAMES[h.role]}</h2><p>Hai investito in <strong>${branch}</strong>. Puoi ritirare una carta della specializzazione opposta.</p><div class="reward-actions">${cards.map(card=>`<button data-prune-role="${h.role}" data-prune-card="${card}">Ritira ${NAMES[card]} · ×${h.deck.filter(value=>value===card).length}</button>`).join('')}<button class="secondary" data-prune-role="${h.role}" data-prune-skip>Non ritirare</button></div><small>Mazzo minimo: 8 carte${h.role==='healer'?' · almeno 2 carte Heal':''}.</small></section>`}
function continueAfterSpecializationPrunes(g){if(g.pendingRewards.length||pendingSpecializationPrunes(g))return;const warrior=g.party.find(h=>h.role==='warrior'),priest=g.party.find(h=>h.role==='healer'),rogue=g.party.find(h=>h.role==='rogue');if(!(warrior&&hasWaitingConversion(warrior)||priest&&hasPriestWaitingConversion(priest)||rogue&&hasRogueWaitingConversion(rogue)))continueAfterRewards(g)}
const renderWithSpecializationPruning=render;
render=function(){renderWithSpecializationPruning();if(!game?.playerBoardEnabled||game.state!=='reward'||!pendingSpecializationPrunes(game))return;document.querySelector('[data-continue-rewards]')?.remove();const party=document.getElementById('party');for(const h of game.party)if(h.pendingPrunes?.length)party.insertAdjacentHTML('beforeend',specializationPrunePanel(h));party.querySelectorAll('[data-prune-role]').forEach(button=>button.onclick=()=>{const h=game.party.find(hero=>hero.role===button.dataset.pruneRole);resolveSpecializationPrune(game,h,button.hasAttribute('data-prune-skip')?null:button.dataset.pruneCard);continueAfterSpecializationPrunes(game);render()})};
const renderWithExclusiveOverlord=render;
render=function(){renderWithExclusiveOverlord();if(!game?.playerBoardEnabled||game.state!=='playing')return;const columns=document.querySelector('.hero-columns');if(!columns)return;const overlordActive=game.activeRole==='overlord';columns.classList.toggle('overlord-only',overlordActive);columns.querySelectorAll(overlordActive?'.hero-column:not(.overlord-column)':'.overlord-column').forEach(column=>column.remove())};
const SAVE_PREFIX='raidwow-save-v1-';
function saveSnapshot(){return JSON.stringify({version:1,savedAt:new Date().toISOString(),game},(key,value)=>key==='hero'&&game.party.includes(value)?{__heroRole:value.role}:value)}
function restoreSnapshot(raw){const snapshot=JSON.parse(raw);if(snapshot.version!==1||!snapshot.game?.party)throw new Error('Salvataggio incompatibile');const restored=snapshot.game;for(const reward of restored.pendingRewards||[])if(reward.hero?.__heroRole)reward.hero=restored.party.find(hero=>hero.role===reward.hero.__heroRole);if(restored.currentEncounter)restored.currentEncounter=restored.telemetry?.encounterEntries?.at(-1)||restored.currentEncounter;return restored}
function saveMetadata(raw){try{const snapshot=JSON.parse(raw),g=snapshot.game,room=g.exploration?.map?.rooms?.find(item=>item.id===g.exploration?.map?.currentRoomId),roles=(g.selectedRoles||g.party?.map(hero=>hero.role)||[]).map(role=>NAMES[role]||role).join(', ');return{date:new Date(snapshot.savedAt).toLocaleString('it-IT'),room:room?.depth||0,round:g.round||1,state:g.state||'—',roles}}catch{return null}}
function createSaveManager(){const overlay=document.createElement('section');overlay.id='saveOverlay';overlay.className='save-overlay';overlay.hidden=true;overlay.innerHTML='<div class="save-panel" role="dialog" aria-modal="true" aria-labelledby="saveTitle"><header><h2 id="saveTitle">Salvataggi</h2><button class="save-close" data-close-saves>Chiudi</button></header><div class="save-slots"></div><p class="save-message" aria-live="polite"></p></div>';document.body.append(overlay);const open=document.createElement('button');open.className='page-tab';open.dataset.openSaves='';open.textContent='Salvataggi';document.querySelector('.page-tabs').append(open);const slots=overlay.querySelector('.save-slots'),message=overlay.querySelector('.save-message');function draw(){slots.innerHTML=Array.from({length:3},(_,index)=>{const slot=index+1,raw=localStorage.getItem(SAVE_PREFIX+slot),meta=raw&&saveMetadata(raw);return`<article class="save-slot"><div><strong>Slot ${slot}${meta?'':' · Vuoto'}</strong>${meta?`<small>Stanza ${meta.room} · Round ${meta.round} · ${meta.state}<br>${meta.roles} · ${meta.date}</small>`:''}</div><div class="save-slot-actions"><button data-save-slot="${slot}">${meta?'Sovrascrivi':'Salva'}</button><button class="secondary" data-load-slot="${slot}" ${meta?'':'disabled'}>Carica</button><button class="secondary" data-delete-slot="${slot}" ${meta?'':'disabled'}>Elimina</button></div></article>`}).join('');slots.querySelectorAll('[data-save-slot]').forEach(button=>button.onclick=()=>{const key=SAVE_PREFIX+button.dataset.saveSlot;if(localStorage.getItem(key)&&!confirm(`Sovrascrivere lo slot ${button.dataset.saveSlot}?`))return;try{localStorage.setItem(key,saveSnapshot());message.textContent=`Partita salvata nello slot ${button.dataset.saveSlot}.`;draw()}catch{message.textContent='Impossibile salvare la partita in questo browser.'}});slots.querySelectorAll('[data-load-slot]').forEach(button=>button.onclick=()=>{if(!confirm('Caricare questa partita e sostituire la sessione corrente?'))return;try{game=restoreSnapshot(localStorage.getItem(SAVE_PREFIX+button.dataset.loadSlot));window.PLAYER_BOARD_SETUP={enabled:!!game.playerBoardEnabled,sides:game.boardSelection||{}};document.getElementById('campaignSetup').hidden=true;overlay.hidden=true;render()}catch{message.textContent='Il salvataggio non può essere caricato.'}});slots.querySelectorAll('[data-delete-slot]').forEach(button=>button.onclick=()=>{if(!confirm(`Eliminare il salvataggio nello slot ${button.dataset.deleteSlot}?`))return;localStorage.removeItem(SAVE_PREFIX+button.dataset.deleteSlot);message.textContent=`Slot ${button.dataset.deleteSlot} eliminato.`;draw()})}document.querySelectorAll('[data-open-saves]').forEach(button=>button.onclick=()=>{message.textContent='';draw();overlay.hidden=false});overlay.querySelector('[data-close-saves]').onclick=()=>overlay.hidden=true;overlay.onclick=event=>{if(event.target===overlay)overlay.hidden=true}}
function createCampaignSetup(){const overlay=document.createElement('section');overlay.id='campaignSetup';overlay.className='campaign-setup';overlay.innerHTML=`<div class="campaign-setup-panel"><h1 class="campaign-title">Le Paludi<br>della Luna<br>Avvelenata</h1><p class="campaign-subtitle">Il Tempio di Grum’Arat</p><div class="campaign-controls"><label>Numero di giocatori<select id="playerCount"><option>1</option><option>2</option><option>3</option><option selected>4</option></select></label><label>Difficoltà<select id="difficulty"><option value="easy">Easy (−10 HP mostri)</option><option value="medium" selected>Medium</option><option value="hardcore">Hardcore (+20 HP mostri)</option></select></label><div class="class-slots" id="classSlots"></div><p class="setup-error" id="setupError"></p><button class="campaign-start" id="enterSwamp">Entra nelle Paludi</button><button class="secondary" data-open-saves>Carica partita</button><p class="setup-credits">Icone carte: <a href="https://game-icons.net" target="_blank" rel="noopener">game-icons.net</a> — CC BY 3.0</p></div></div>`;document.body.append(overlay);const count=overlay.querySelector('#playerCount'),slots=overlay.querySelector('#classSlots'),classes=[['warrior','Guerriero'],['healer','Prete'],['rogue','Rogue'],['mage','Mago']];function draw(){const n=+count.value;slots.innerHTML=Array.from({length:n},(_,i)=>`<label>Giocatore ${i+1}<select class="class-choice">${classes.map(([id,name],j)=>`<option value="${id}" ${i===j?'selected':''}>${name}</option>`).join('')}</select></label>`).join('')}count.onchange=draw;draw();overlay.querySelector('#enterSwamp').onclick=()=>{const roles=[...overlay.querySelectorAll('.class-choice')].map(select=>select.value),error=overlay.querySelector('#setupError');if(new Set(roles).size!==roles.length){error.textContent='Ogni classe può essere scelta una sola volta.';return}startBoardCampaign(roles,overlay.querySelector('#difficulty')?.value||'medium');overlay.hidden=true}};
function startBoardCampaign(roles=['warrior','healer','rogue','mage'],difficulty='medium'){const sides={warrior:'front',healer:'front',rogue:'front',mage:'front',roles};window.PLAYER_BOARD_SETUP={enabled:true,sides};game=resetConnectedCampaignToEntrance(startExplorationGame(EXPLORATION_CONFIG_T7_B,true));game.difficulty=difficulty;applyPlayerBoardEnemyStats(game);render()}
document.getElementById('startBoard').onclick=startBoardCampaign;
document.getElementById('startLegacy').onclick=()=>{window.PLAYER_BOARD_SETUP={enabled:false,sides:{}};game=newGame(true);render()};
document.getElementById('reset').onclick=()=>{document.getElementById('campaignSetup').hidden=false};
document.getElementById('end').onclick=()=>{if(game.playerBoardEnabled)passHeroTurn(game);else endRound(game);render()};
document.getElementById('boardSmoke').onclick=()=>{const previous=window.PLAYER_BOARD_SETUP;window.PLAYER_BOARD_SETUP={enabled:false,sides:{}};const legacy=legacyNewGame(true),board=attachBoard(legacyNewGame(true),{warrior:'front',healer:'front'}),w=board.party[0],deckBefore=w.deck.length;boardInvest(board,w,'parry');boardInvest(board,w,'parry');const trackPass=w.mastery.parry===2&&w.levels.parry===2&&w.deck.length===deckBefore;addDeckCard(w,'parry');const deckPass=w.deck.length===deckBefore+1&&w.mastery.parry===2;w.hp=w.maxHp+1;const hpViolation=validateBoard(board).length===1;w.hp=w.maxHp;const events=board.playerBoardAudit.events.map(e=>e.type);const result={test:'Player Board feature-flag smoke',passed:!legacy.playerBoardEnabled&&trackPass&&deckPass&&hpViolation&&events.includes('ENGINE_INVESTED')&&events.includes('ABILITY_LEVEL_UP')&&events.includes('PLAYER_BOARD_SIDE_SELECTED'),baselineUnchanged:!legacy.playerBoardEnabled,trackPass,deckPass,hpViolation,audit:board.playerBoardAudit};document.getElementById('results').textContent=JSON.stringify(result,null,2);window.PLAYER_BOARD_SETUP=previous};
if(new URLSearchParams(location.search).get('legacy')==='1')render();else createCampaignSetup();
createSaveManager();

const HERO_ART={warrior:'assets/eroe-guerriero.jpeg',healer:'assets/eroe-priest.jpeg',rogue:'assets/eroe-rogue.jpeg',mage:'assets/eroe-mago.jpeg'};
function heroArt(h){return h&&h.role==='warrior'&&h.twoHanded?'assets/eroe-guerriero-2h.jpeg':HERO_ART[h&&h.role]}

/* ponytail: card-first friendly-target picker for support abilities.
   Click a heal/support card -> pending state, the #enemies target list flips to
   allies (HP bar + accumulated Wounds), click an ally to resolve. Slow Heal shows
   the picker only on the completing (2nd) card, since only completion heals.
   Purely reorders the existing play() call: same action cost / card consumption. */
(function(){
  function friendlyPickNow(g,h,card){
    if(!g||!g.playerBoardEnabled||!['playing','restoring'].includes(g.state)||h.role!=='healer')return false;
    if(card==='quick_heal'||card==='holy_shield'||card==='bandage')return true; // L3 (tutti/split): il pick soddisfa il target richiesto dall'engine
    if(card==='slow_heal')return !!h.casting;                                   // solo la 2a carta (completamento)
    return false;
  }
  function renderFriendlyTargets(g){
    const p=g.pendingFriendly,label=NAMES[p.card]||p.card;
    const list=aliveHeroes(g).map(h=>{
      const cfg=h.board&&h.board.config,name=(cfg&&cfg.className)||NAMES[h.role]||h.role;
      const wounds=h.deck.filter(c=>c==='wound').length;
      const pips=Array.from({length:h.maxHp},(_,k)=>`<i class="${k<h.hp?'full':''}"></i>`).join('');
      const extra=(h.shield>0?` · 🛡 ${h.shield}`:'')+(h.casting?' · ✨ Cast':'');
      return `<button class="room-target friendly-pick has-art" data-ally-pick="${h.role}"><img class="enemy-art" src="${heroArt(h)}" alt="" aria-hidden="true"><strong>${name}</strong><div class="hp-track"><strong>HP ${Math.max(0,h.hp)}/${h.maxHp}</strong><span class="hp-pips">${pips}</span></div><small>${wounds?`🩹 ${wounds} Ferit${wounds===1?'a':'e'}`:'Nessuna ferita'}${extra}</small></button>`;
    }).join('');
    document.getElementById('enemies').innerHTML=`<h2>${label} — scegli un alleato</h2><p class="target-help">Tocca l'alleato da curare o supportare.</p><div class="room-targets">${list}</div>`;
    const hidden=document.getElementById('target');if(hidden)hidden.value=g.selectedTarget||'';
  }
  const _renderRoomTargets=renderRoomTargets;
  renderRoomTargets=function(g){if(g&&g.pendingFriendly){renderFriendlyTargets(g);return}return _renderRoomTargets(g)};
  const _sync=syncMobileTargetBar;
  syncMobileTargetBar=function(){_sync();if(game&&game.pendingFriendly){const s=document.querySelector('.mobile-target-bar>strong');if(s)s.textContent='Scegli un alleato'}};
  const _pass=passHeroTurn;
  passHeroTurn=function(g){if(g)g.pendingFriendly=null;return _pass(g)};

  document.addEventListener('click',function(ev){
    const g=game;if(!g||!g.playerBoardEnabled)return;
    const pick=ev.target.closest('.friendly-pick[data-ally-pick]');
    if(pick&&g.pendingFriendly){
      ev.stopImmediatePropagation();ev.preventDefault();
      const p=g.pendingFriendly,h=g.party.find(x=>x.role===p.role);
      g.selectedTarget=`ally:${pick.dataset.allyPick}:0`;
      const played=h&&play(g,h,p.card,g.selectedTarget);
      g.pendingFriendly=null;automaticEnemyTarget(g);
      if(!played)note(g,'Giocata non valida per il bersaglio o il timing scelto.');else advanceHeroTurn(g);
      render();return;
    }
    const cardBtn=ev.target.closest('[data-h][data-i]');
    if(cardBtn){
      const h=g.party[+cardBtn.dataset.h],card=h&&h.hand[+cardBtn.dataset.i];
      if(h&&card&&friendlyPickNow(g,h,card)){ev.stopImmediatePropagation();ev.preventDefault();g.pendingFriendly={role:h.role,card};render();return}
    }
    // clic su un'altra abilita/equip (bersaglio nemico) mentre il picker e attivo: annulla, torna ai nemici e lascia proseguire la carta
    if(g.pendingFriendly&&ev.target.closest('[data-h],[data-war-tech],[data-rogue-tech],[data-critical],[data-sword],[data-shield],[data-dagger],[data-wand],[data-flip]')){g.pendingFriendly=null;automaticEnemyTarget(g)}
  },true);
})();
